package com.evi.live;
import java.lang.reflect.*;
import net.runelite.api.*;

/** Local synthetic offers only; never launches a game client. */
public class EviLiveObservationTest {
  static class FakeOffer implements GrandExchangeOffer {
    final GrandExchangeOfferState state; final int filled;
    FakeOffer(GrandExchangeOfferState state,int filled){this.state=state;this.filled=filled;}
    public int getQuantitySold(){return filled;}
    public int getItemId(){return 1;}
    public int getTotalQuantity(){return 10;}
    public long getPrice(){return 100;}
    public long getSpent(){return (long)filled*100;}
    public GrandExchangeOfferState getState(){return state;}
  }
  static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
  public static void main(String[] args) throws Exception {
    EviLivePlugin plugin=new EviLivePlugin();
    ItemComposition item=(ItemComposition)Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),new Class[]{ItemComposition.class},(p,m,a)->m.getName().equals("getName")?"Synthetic rune":null);
    Client client=(Client)Proxy.newProxyInstance(Client.class.getClassLoader(),new Class[]{Client.class},(p,m,a)->m.getName().equals("getItemDefinition")?item:null);
    Field f=EviLivePlugin.class.getDeclaredField("client");f.setAccessible(true);f.set(plugin,client);
    Method capture=EviLivePlugin.class.getDeclaredMethod("capture",int.class,GrandExchangeOffer.class,EviLivePlugin.Offer.class,boolean.class);capture.setAccessible(true);
    EviLivePlugin.Offer baseline=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BOUGHT,10),null,false);
    check(!baseline.knownStart,"Login completion must remain baseline");
    EviLivePlugin.Offer empty=(EviLivePlugin.Offer)capture.invoke(plugin,0,null,null,false);
    EviLivePlugin.Offer start=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BUYING,0),empty,true);
    check(start.knownStart,"A new zero-fill offer after observed empty is known");
    EviLivePlugin.Offer partial=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BUYING,4),start,true);
    check(partial.offerId.equals(start.offerId)&&partial.knownStart,"Partial fill retains identity");
    EviLivePlugin.Offer cancel=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.CANCELLED_BUY,4),partial,true);
    check(cancel.offerId.equals(start.offerId),"Cancellation retains identity");
    EviLivePlugin.Offer reused=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BUYING,0),cancel,true);
    check(!reused.offerId.equals(start.offerId)&&!reused.knownStart,"Slot reuse without observed empty must rebaseline");
    EviLivePlugin.Offer instant=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BOUGHT,10),empty,true);
    check(!instant.knownStart,"Instant fill without observed zero must remain incomplete");
    EviLivePlugin.Offer complete=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BOUGHT,10),partial,true);
    check(complete.knownStart&&complete.offerId.equals(start.offerId),"Observed buy completion retains identity");
    EviLivePlugin.Offer duplicate=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BOUGHT,10),complete,true);
    check(duplicate.offerId.equals(complete.offerId),"Repeated completion is the same offer");
    EviLivePlugin.Offer sell=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.SELLING,0),empty,true);
    EviLivePlugin.Offer sold=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.SOLD,10),sell,true);
    check(sold.knownStart&&sold.offerId.equals(sell.offerId),"Observed sale retains identity");
    EviLivePlugin.Offer reverse=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BUYING,0),sell,true);
    check(!reverse.offerId.equals(sell.offerId)&&!reverse.knownStart,"Buy and sell cannot share identity");
    EviLivePlugin.Offer regression=(EviLivePlugin.Offer)capture.invoke(plugin,0,new FakeOffer(GrandExchangeOfferState.BUYING,2),partial,true);
    check(!regression.offerId.equals(partial.offerId)&&!regression.knownStart,"Regressing filled counters start incomplete observation");
    Method reset=EviLivePlugin.class.getDeclaredMethod("reset");reset.setAccessible(true);reset.invoke(plugin);
    Field session=EviLivePlugin.class.getDeclaredField("session");session.setAccessible(true);String oldSession=(String)session.get(plugin);
    reset.invoke(plugin);check(!oldSession.equals(session.get(plugin)),"Reconnect creates a new session");
    Field slots=EviLivePlugin.class.getDeclaredField("slots");slots.setAccessible(true);
    for(EviLivePlugin.Offer slot:(EviLivePlugin.Offer[])slots.get(plugin))check(slot==null,"Reconnect clears prior slot baselines");
    System.out.println("PASS: baseline, partial/cancel/instant/completed buys and sells, duplicate events, counter regression, slot reuse and session reset");
  }
}

package com.evi.live;

import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;

/**
 * Fake widget/client only; never launches a game client. Covers SuggestionSearchHighlightOverlay:
 * finds the suggested item's row in the GE's own item-search results list by item ID (skipping a
 * missing or hidden results widget, a non-matching child, or a matching-but-hidden child); that
 * render() itself respects the display toggle, the GE-slot-open gate, a cached suggestion, NOT
 * already being at the quantity/price prompt, and the suggested item not already being the one
 * selected. The clickable "EVI item: <icon> <name>" jump-to-item row lives in
 * SuggestionItemSelectWidget instead (see EviLiveItemSelectWidgetTest), not this overlay -- this
 * overlay only ever paints a translucent highlight, never creates a real widget or a click
 * listener. Reuses EviLiveSuggestionTest's FakeClient/FakeWidget fixtures rather than duplicating
 * them.
 */
public class EviLiveSearchHighlightTest {
  static void check(boolean value, String message) { if (!value) throw new AssertionError(message); }

  static void set(Object target, String name, Object value) throws Exception {
    Field f = target.getClass().getDeclaredField(name);
    f.setAccessible(true);
    f.set(target, value);
  }

  static boolean painted(BufferedImage img, int x, int y) { return (img.getRGB(x, y) >>> 24) != 0; }

  public static void main(String[] args) throws Exception {
    EviLiveSuggestionTest.FakeClient fc = new EviLiveSuggestionTest.FakeClient();
    // Not the numeric quantity/price chatbox input type -- represents the item-picking phase,
    // before the prompt SuggestionHintWidget handles. The fixture's own default (7) is that
    // prompt's input type, so it must be changed here or isPromptOpen() reads true immediately.
    fc.inputType = 0;
    Client client = fc.proxy();
    GEOffer geOffer = new GEOffer();
    set(geOffer, "client", client);
    SuggestionCache cache = new SuggestionCache();
    EviLiveConfig enabled = (EviLiveConfig) Proxy.newProxyInstance(EviLiveConfig.class.getClassLoader(), new Class[]{EviLiveConfig.class},
      (p, m, a) -> "showSuggestionHint".equals(m.getName()) ? Boolean.TRUE : null);

    SuggestionSearchHighlightOverlay overlay = new SuggestionSearchHighlightOverlay();
    set(overlay, "client", client);
    set(overlay, "geOffer", geOffer);
    set(overlay, "suggestionCache", cache);
    set(overlay, "config", enabled);

    Method findRow = SuggestionSearchHighlightOverlay.class.getDeclaredMethod("findSuggestionRow", int.class);
    findRow.setAccessible(true);

    // -- findSuggestionRow: the lookup itself. --
    check(findRow.invoke(overlay, 1) == null, "No search-results widget at all: nothing to highlight");

    fc.searchResults = new EviLiveSuggestionTest.FakeWidget();
    fc.searchResults.hidden = true;
    check(findRow.invoke(overlay, 1) == null, "Hidden search-results widget: nothing to highlight");

    fc.searchResults.hidden = false;
    EviLiveSuggestionTest.FakeWidget other = new EviLiveSuggestionTest.FakeWidget();
    other.itemId = 999;
    fc.searchResults.dynamicChildren.add(other);
    check(findRow.invoke(overlay, 1) == null, "No child matches the item ID: nothing to highlight");

    EviLiveSuggestionTest.FakeWidget match = new EviLiveSuggestionTest.FakeWidget();
    match.itemId = 1;
    match.bounds = new Rectangle(5, 10, 40, 32);
    fc.searchResults.dynamicChildren.add(match);
    check(findRow.invoke(overlay, 1) != null, "A visible, matching child must be found");

    match.hidden = true;
    check(findRow.invoke(overlay, 1) == null, "A matching but hidden child must not be used");
    match.hidden = false;

    // -- render(): the config toggle, the GE-slot-open gate, a cached suggestion, not already at
    // the prompt, and the item not already selected, end to end (the row highlight only). --
    fc.openSlotVarbit = 1; // GE slot open, required by the overlay's own gate
    cache.set(EviLiveSuggestionTest.suggestion(1, "buy", 100, 50, 65));
    BufferedImage img = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
    overlay.render(img.createGraphics());
    check(painted(img, 10, 15), "A matching, visible row must actually be painted onto the overlay's graphics");

    fc.openSlotVarbit = 0;
    BufferedImage noSlot = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
    overlay.render(noSlot.createGraphics());
    check(!painted(noSlot, 10, 15), "No GE slot open: nothing must be painted even with a matching row cached");
    fc.openSlotVarbit = 1;

    fc.inputType = 7; // the real quantity/price chatbox input type: already past item-picking
    BufferedImage promptOpen = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
    overlay.render(promptOpen.createGraphics());
    check(!painted(promptOpen, 10, 15), "Already at the quantity/price prompt: the row highlight must not paint (SuggestionHintWidget's job now)");
    fc.inputType = 0;

    fc.currentItemId = 1; // the suggested item is already the one selected
    BufferedImage alreadySelected = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
    overlay.render(alreadySelected.createGraphics());
    check(!painted(alreadySelected, 10, 15), "Suggested item already selected: nothing left to point at, must not paint");
    fc.currentItemId = -1;

    EviLiveConfig disabled = (EviLiveConfig) Proxy.newProxyInstance(EviLiveConfig.class.getClassLoader(), new Class[]{EviLiveConfig.class},
      (p, m, a) -> "showSuggestionHint".equals(m.getName()) ? Boolean.FALSE : null);
    set(overlay, "config", disabled);
    BufferedImage toggledOff = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
    overlay.render(toggledOff.createGraphics());
    check(!painted(toggledOff, 10, 15), "Display toggle off: nothing must be painted");
    set(overlay, "config", enabled);

    cache.set(null);
    BufferedImage noSuggestion = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
    overlay.render(noSuggestion.createGraphics());
    check(!painted(noSuggestion, 10, 15), "No cached suggestion: nothing must be painted");

    System.out.println("PASS: search-results row lookup by item ID (missing/hidden widget, no match, hidden match), render() gating on the display toggle, GE-slot-open, a cached suggestion, the quantity/price prompt, and an already-selected item");
  }
}

package com.evi.live;
import java.util.EnumSet;
import net.runelite.api.WorldType;

public final class EconomyScopeTest {
  public static void main(String[] args) {
    if(!EconomyScope.of(EnumSet.noneOf(WorldType.class)).isEmpty())throw new AssertionError("Free worlds share ordinary economy");
    if(!EconomyScope.of(EnumSet.of(WorldType.MEMBERS,WorldType.PVP,WorldType.HIGH_RISK)).isEmpty())throw new AssertionError("Ordinary world flags must not split account history");
    for(WorldType type:new WorldType[]{WorldType.DEADMAN,WorldType.SEASONAL,WorldType.FRESH_START_WORLD,WorldType.BETA_WORLD,WorldType.NOSAVE_MODE,WorldType.TOURNAMENT_WORLD}) {
      if(EconomyScope.of(EnumSet.of(type,WorldType.MEMBERS)).isEmpty())throw new AssertionError("Special economy merged into main: "+type);
    }
    if(EconomyScope.of(EnumSet.of(WorldType.DEADMAN)).equals(EconomyScope.of(EnumSet.of(WorldType.DEADMAN,WorldType.SEASONAL))))throw new AssertionError("Seasonal and permanent modes must remain separate");
    if(EconomyScope.of(null).isEmpty())throw new AssertionError("Unknown world is not ordinary economy");
    System.out.println("PASS: ordinary-world identity continuity and special-economy separation");
  }
}

package com.evi.live;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;

/**
 * Fake widget/client only; never launches a game client and never dispatches a real keyboard or
 * mouse event -- setOnOpListener/setOnKeyListener calls are captured as plain data
 * (EviLiveSuggestionTest.FakeWidget.onOpArgs/onKeyArgs), never invoked. Covers
 * SuggestionItemSelectWidget: the same visibility gate the row highlight and hint widget share (the
 * display toggle, a GE slot open, NOT already at the quantity/price prompt, a cached suggestion,
 * the suggested item not already selected), plus its own gate on the item-search results widget
 * actually existing (search genuinely open). Covers that update() creates exactly three child
 * widgets (a clickable backdrop, a text label, an item icon) wired with the exact script/argument
 * values Flipping Copilot's own published source uses for its equivalent row (see the widget's own
 * class doc for where that came from and why), that repeated updates for the same item reuse those
 * three widgets rather than creating duplicates, that a changed suggested item updates them in
 * place (still exactly three), and that every gating condition drops the widget references without
 * creating anything. Reuses EviLiveSuggestionTest's FakeClient/FakeWidget/suggestion() fixtures.
 */
public class EviLiveItemSelectWidgetTest {
  static void check(boolean value, String message) { if (!value) throw new AssertionError(message); }

  static void set(Object target, String name, Object value) throws Exception {
    Field f = target.getClass().getDeclaredField(name);
    f.setAccessible(true);
    f.set(target, value);
  }

  public static void main(String[] args) throws Exception {
    EviLiveSuggestionTest.FakeClient fc = new EviLiveSuggestionTest.FakeClient();
    fc.inputType = 0; // item-picking phase, not the quantity/price prompt
    Client client = fc.proxy();
    GEOffer geOffer = new GEOffer();
    set(geOffer, "client", client);
    SuggestionCache cache = new SuggestionCache();
    EviLiveConfig enabled = (EviLiveConfig) Proxy.newProxyInstance(EviLiveConfig.class.getClassLoader(), new Class[]{EviLiveConfig.class},
      (p, m, a) -> "showSuggestionHint".equals(m.getName()) ? Boolean.TRUE : null);

    SuggestionItemSelectWidget widget = new SuggestionItemSelectWidget();
    set(widget, "client", client);
    set(widget, "geOffer", geOffer);
    set(widget, "suggestionCache", cache);
    set(widget, "config", enabled);

    // -- Gating: none of these must create anything. --
    widget.update();
    check(fc.searchResults == null, "sanity: no search-results widget wired up yet");

    fc.searchResults = new EviLiveSuggestionTest.FakeWidget();
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "No GE slot open: nothing must be created");

    fc.openSlotVarbit = 1;
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "No cached suggestion: nothing must be created");

    cache.set(EviLiveSuggestionTest.suggestion(1, "buy", 100, 50, 65));
    fc.inputType = 7; // the real quantity/price prompt: already past item-picking
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "Already at the quantity/price prompt: nothing must be created");
    fc.inputType = 0;

    fc.currentItemId = 1; // the suggested item is already the one selected
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "Suggested item already selected: nothing left to point at, nothing created");
    fc.currentItemId = -1;

    EviLiveSuggestionTest.FakeWidget savedResults = fc.searchResults;
    fc.searchResults = null;
    widget.update();
    check(savedResults.createdChildren.isEmpty(), "No search-results widget (search not open yet): nothing must be created");
    fc.searchResults = savedResults;

    EviLiveConfig disabled = (EviLiveConfig) Proxy.newProxyInstance(EviLiveConfig.class.getClassLoader(), new Class[]{EviLiveConfig.class},
      (p, m, a) -> Boolean.FALSE);
    set(widget, "config", disabled);
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "Display toggle off: nothing must be created");
    set(widget, "config", enabled);

    // -- The actual creation, with everything eligible. --
    widget.update();
    check(fc.searchResults.createdChildren.size() == 3, "Must create exactly three child widgets: a clickable row, a text label, and an item icon");
    EviLiveSuggestionTest.FakeWidget row = fc.searchResults.createdChildren.get(0);
    EviLiveSuggestionTest.FakeWidget text = fc.searchResults.createdChildren.get(1);
    EviLiveSuggestionTest.FakeWidget icon = fc.searchResults.createdChildren.get(2);
    check(row.onOpArgs != null && row.onOpArgs.length == 3 && (int) row.onOpArgs[0] == 754 && (int) row.onOpArgs[1] == 1 && (int) row.onOpArgs[2] == 84,
      "The clickable row must be wired with the exact script/itemId/arg triple a genuine GE search-result row carries (on click)");
    check(row.onKeyArgs != null && row.onKeyArgs.length == 3 && (int) row.onKeyArgs[0] == 754 && (int) row.onKeyArgs[1] == 1 && (int) row.onKeyArgs[2] == -2147483640,
      "The clickable row must be wired with the exact script/itemId/arg triple a genuine GE search-result row carries (on Enter/key-select)");
    check(text.text != null && text.text.contains("EVI item:") && text.text.contains("Test item"), "The label must name the suggested item: " + text.text);
    check(icon.itemId == 1, "The icon must be the suggested item's own icon");
    // Placement: one row under the top line (where the game's previous search and Copilot's own row
    // sit), in fixed high child slots so an indexed write to slots 0-3 can never replace them.
    check(row.originalY == 32 && text.originalY == 32, "The row must sit one row below the top line, with or without other plugins: " + row.originalY);
    check(fc.searchResults.children.get(60) == row && fc.searchResults.children.get(61) == text && fc.searchResults.children.get(62) == icon,
      "The row, text and icon must occupy their fixed slots 60-62");
    check(!row.hidden, "With nothing typed, the row must be visible");

    // -- Reuse: updating again for the SAME item must not create more widgets. --
    widget.update();
    check(fc.searchResults.createdChildren.size() == 3, "Repeated updates for the same item must reuse the same three widgets, not duplicate them");

    // -- Another plugin (or the game rebuilding the list) takes over a slot: the row must come back. --
    fc.searchResults.children.put(60, new EviLiveSuggestionTest.FakeWidget());
    widget.update();
    check(fc.searchResults.createdChildren.size() == 6, "A replaced slot must be noticed and the row recreated, not left detached and invisible");
    row = fc.searchResults.createdChildren.get(3);
    text = fc.searchResults.createdChildren.get(4);
    icon = fc.searchResults.createdChildren.get(5);
    check(icon.itemId == 1 && row.onOpArgs != null && (int) row.onOpArgs[1] == 1, "The recreated row must point at the suggested item again");
    // Writes by index into the top line's slots (what Copilot does) must not disturb it.
    fc.searchResults.children.put(0, new EviLiveSuggestionTest.FakeWidget());
    fc.searchResults.children.put(3, new EviLiveSuggestionTest.FakeWidget());
    widget.update();
    check(fc.searchResults.createdChildren.size() == 6, "Writes to slots 0-3 must leave the row alone");

    // -- Typing: the live results own that space, so the row hides, and returns when cleared. --
    fc.typedSearch = "rune";
    widget.update();
    check(row.hidden && text.hidden && icon.hidden, "While a search is typed, the row must be hidden");
    check(fc.searchResults.createdChildren.size() == 6, "Typing must not create anything");
    fc.typedSearch = "";
    widget.update();
    check(!row.hidden && !text.hidden && !icon.hidden, "With the search box empty again, the row must be visible again");

    // -- Item change while still open: still exactly three widgets, but updated to the new item. --
    cache.set(EviLiveSuggestionTest.suggestion(2, "buy", 50, 200, 260));
    widget.update();
    check(fc.searchResults.createdChildren.size() == 6, "A changed suggested item must update the existing three widgets, not create new ones");
    check(row.onOpArgs != null && (int) row.onOpArgs[1] == 2, "The row's click target must switch to the new suggested item");
    check(icon.itemId == 2, "The icon must switch to the new suggested item");

    // -- Clearing: once the item becomes the one selected, references are dropped -- a later fresh
    // eligibility (a different, not-yet-selected suggestion) must create a fresh set of widgets. --
    fc.currentItemId = 2;
    widget.update();
    check(fc.searchResults.createdChildren.size() == 6, "Selecting the item must not itself create anything more");
    fc.currentItemId = -1;
    cache.set(EviLiveSuggestionTest.suggestion(3, "buy", 20, 400, 480));
    widget.update();
    check(fc.searchResults.createdChildren.size() == 9, "After the widget was cleared (item selected), a new eligible suggestion must create a fresh set of widgets");

    System.out.println("PASS: placement one row below the top line in fixed slots 60-62; recreation when a slot is taken over; untouched by writes to slots 0-3; hidden while typing and back when cleared; gating on the display toggle, GE-slot-open, the quantity/price prompt, a cached suggestion, an already-selected item, and the search-results widget existing; exactly-three-widget creation wired with Flipping Copilot's own verified script/argument values; reuse across repeated updates and item changes; and fresh creation after a clear");
  }
}

package com.evi.live;

import com.google.gson.Gson;
import java.awt.event.KeyEvent;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ModifierlessKeybind;

/**
 * Fake widget/client only; never launches a game client and never touches the Confirm button
 * or a menu action. Asserts the hotkey writes the exact expected string and nothing else.
 */
public class EviLiveSuggestionTest {
  static void check(boolean value, String message) { if (!value) throw new AssertionError(message); }

  static class FakeWidget {
    String text = "";
    int originalY;
    int itemId = -1;
    boolean hidden = false;
    java.awt.Rectangle bounds;
    // Captured for SuggestionItemSelectWidget's tests: the exact (script, itemId, arg) triple
    // passed to setOnOpListener/setOnKeyListener, and the widget's name (used for its tooltip/menu
    // label, same as a real GE search-result row).
    Object[] onOpArgs;
    Object[] onKeyArgs;
    String name;
    Map<Integer, FakeWidget> children = new HashMap<>();
    // Populated by createChild(), so a test can inspect every child widget a caller created on
    // this fake (e.g. the chatbox container in EviLiveHintTest), in creation order.
    java.util.List<FakeWidget> createdChildren = new java.util.ArrayList<>();
    // Distinct from children/createdChildren (which key by fixed child index): models
    // getDynamicChildren(), the list-style children of a search results widget, keyed by nothing
    // but position, for EviLiveSearchHighlightTest.
    java.util.List<FakeWidget> dynamicChildren = new java.util.ArrayList<>();
    // One proxy per fake, like the real client, which hands back the same widget object every time --
    // SuggestionItemSelectWidget relies on that identity to tell whether its widgets are still attached.
    private Widget cached;
    Widget proxy() {
      if (cached != null) return cached;
      return cached = (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class[]{Widget.class}, (p, m, a) -> {
        switch (m.getName()) {
          case "getText": return text;
          case "setText": text = (String) a[0]; return null;
          case "getChild": return children.containsKey(a[0]) ? children.get((Integer) a[0]).proxy() : null;
          case "createChild": {
            FakeWidget child = new FakeWidget();
            createdChildren.add(child);
            // A real index replaces whatever held that slot, as in the client; -1 appends.
            if (a != null && a.length > 0 && a[0] instanceof Integer && (Integer) a[0] >= 0) children.put((Integer) a[0], child);
            return child.proxy();
          }
          case "getOriginalY": return originalY;
          case "setOriginalY": originalY = (Integer) a[0]; return null;
          case "getItemId": return itemId;
          case "isHidden": return hidden;
          case "isSelfHidden": return hidden;
          case "setHidden": hidden = (Boolean) a[0]; return null;
          case "getBounds": return bounds;
          case "getDynamicChildren": return dynamicChildren.stream().map(FakeWidget::proxy).toArray(Widget[]::new);
          case "setOnOpListener": onOpArgs = (Object[]) a[0]; return null;
          case "setOnKeyListener": onKeyArgs = (Object[]) a[0]; return null;
          case "setName": name = (String) a[0]; return null;
          case "setItemId": itemId = (Integer) a[0]; return null;
          // Styling/layout/listener setters the hint widget calls but this fixture doesn't need to
          // model beyond accepting the call; revalidate/setOriginalX/etc. are no-ops here.
          default: return null;
        }
      });
    }
  }

  static class FakeClient {
    int openSlotVarbit = 0; // CURRENTLY_OPEN_GE_SLOT_VARBIT_ID raw value; 0 means "no slot open" (getOpenSlot() == -1)
    int offerCreationType = 0; // 0 = buying, 1 = selling (Varbits.GE_OFFER_CREATION_TYPE)
    int currentItemId = -1;
    int inputType = 7;
    FakeWidget chatboxTitle = new FakeWidget();
    FakeWidget chatboxInput = new FakeWidget();
    FakeWidget offerContainer = new FakeWidget();
    FakeWidget chatboxContainer = new FakeWidget();
    // Null by default, modelling the GE item-search results widget not existing yet (e.g. the
    // search box isn't open); EviLiveSearchHighlightTest assigns one in to exercise the rest.
    FakeWidget searchResults;
    String lastVarcStr;
    // What the player has typed into the chatbox input (VarClientStr.INPUT_TEXT); empty by default.
    String typedSearch = "";

    Client proxy() {
      return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class[]{Client.class}, (p, m, a) -> {
        switch (m.getName()) {
          case "getVarbitValue": {
            boolean isSlotVarbit = a[0] instanceof Integer && (Integer) a[0] == 4439;
            return isSlotVarbit ? openSlotVarbit : offerCreationType;
          }
          case "getVarpValue": return currentItemId;
          case "getVarcIntValue": return inputType;
          case "getWidget": {
            Object id = a[0];
            if (ComponentID.CHATBOX_TITLE == asInt(id)) return chatboxTitle.proxy();
            if (ComponentID.CHATBOX_FULL_INPUT == asInt(id)) return chatboxInput.proxy();
            if (ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER == asInt(id)) return offerContainer.proxy();
            if (ComponentID.CHATBOX_CONTAINER == asInt(id)) return chatboxContainer.proxy();
            if (ComponentID.CHATBOX_GE_SEARCH_RESULTS == asInt(id)) return searchResults == null ? null : searchResults.proxy();
            return null;
          }
          case "setVarcStrValue": lastVarcStr = (String) a[1]; return null;
          case "getVarcStrValue": return typedSearch;
          default: return primitiveDefault(m.getReturnType());
        }
      });
    }
    private static int asInt(Object o) { return o instanceof Integer ? (Integer) o : -1; }
    private static Object primitiveDefault(Class<?> t) {
      if (t == boolean.class) return false;
      if (t == int.class) return 0;
      return null;
    }
  }

  /** buyPrice and sellPrice are always both set, matching what the bridge actually sends now. */
  static Suggestion suggestion(int itemId, String action, int quantity, int buyPrice, int sellPrice) {
    Suggestion s = new Suggestion();
    s.itemId = itemId; s.action = action; s.quantity = quantity; s.buyPrice = buyPrice; s.sellPrice = sellPrice; s.name = "Test item"; s.source = "personal";
    return s;
  }

  /** Models a bridge openItemPrice response: quantity always 0, name/action/source/reasoning left
   *  unset, exactly as OpenItemPriceCache's own class doc describes. */
  static Suggestion openItemPrice(int itemId, int buyPrice, int sellPrice) {
    Suggestion s = new Suggestion();
    s.itemId = itemId; s.buyPrice = buyPrice; s.sellPrice = sellPrice;
    return s;
  }

  public static void main(String[] args) throws Exception {
    // The bridge's real JSON shape must still deserialize into the plugin's field names, including
    // the separate openItemPrice field (a plain {itemId, buyPrice, sellPrice} shape -- no name,
    // action, quantity, source, or reasoning -- see OpenItemPriceCache's own class doc).
    String json = "{\"suggestion\":{\"itemId\":13190,\"name\":\"Fire rune\",\"action\":\"buy\",\"quantity\":500,\"buyPrice\":4,\"sellPrice\":5,\"source\":\"personal\",\"reasoning\":\"test\"},\"openItemPrice\":{\"itemId\":314,\"buyPrice\":180,\"sellPrice\":210}}";
    EviLivePlugin.SuggestionResponse parsed = new Gson().fromJson(json, EviLivePlugin.SuggestionResponse.class);
    check(parsed.suggestion.itemId == 13190 && "buy".equals(parsed.suggestion.action) && parsed.suggestion.quantity == 500
      && parsed.suggestion.buyPrice == 4 && parsed.suggestion.sellPrice == 5, "Bridge JSON shape must round-trip into plugin fields");
    check(parsed.openItemPrice.itemId == 314 && parsed.openItemPrice.buyPrice == 180 && parsed.openItemPrice.sellPrice == 210
      && parsed.openItemPrice.quantity == 0 && parsed.openItemPrice.name == null, "openItemPrice must round-trip as a plain price with no name/quantity");

    FakeClient fc = new FakeClient();
    Client client = fc.proxy();
    GEOffer geOffer = new GEOffer();
    Field clientField = GEOffer.class.getDeclaredField("client"); clientField.setAccessible(true); clientField.set(geOffer, client);
    SuggestionCache cache = new SuggestionCache();
    OpenItemPriceCache openItemPriceCache = new OpenItemPriceCache();
    SuggestionKeybindHandler handler = new SuggestionKeybindHandler(null, null, client, geOffer, cache, openItemPriceCache, null);
    Method fill = SuggestionKeybindHandler.class.getDeclaredMethod("fill"); fill.setAccessible(true);

    // No GE slot open at all: nothing should be touched even with a cached suggestion.
    cache.set(suggestion(1, "buy", 100, 50, 65));
    fc.currentItemId = 1;
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty() && fc.lastVarcStr == null, "Hotkey must do nothing when no GE slot is open");

    // Slot open, but neither the quantity nor price prompt is the open chatbox.
    fc.openSlotVarbit = 1;
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must do nothing when the open chatbox is not the quantity/price prompt");

    // Quantity prompt open, matching item: fills quantity, exact string, touches nothing else.
    fc.chatboxTitle.text = "How many do you wish to buy?";
    fill.invoke(handler);
    check("100*".equals(fc.chatboxInput.text), "Hotkey must fill the exact suggested quantity");
    check("100".equals(fc.lastVarcStr), "Hotkey must set the matching VarClientStr value");

    // Different item selected in-game than the cached suggestion: must not fill.
    fc.chatboxInput.text = "";
    fc.lastVarcStr = null;
    fc.currentItemId = 999;
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must not fill a suggestion for a different item than is currently selected");

    // Price prompt, buy side, matching item: fills the suggestion's buy price.
    fc.currentItemId = 1;
    fc.chatboxTitle.text = "Set a price for each item:";
    fc.offerContainer.children.put(20, new FakeWidget());
    fc.offerContainer.children.get(20).text = "Buy offer";
    fill.invoke(handler);
    check("50*".equals(fc.chatboxInput.text), "Hotkey must fill the exact suggested buy price");

    // Price prompt, same item, but the player is actually selling: this is the same flip's other
    // side, so it must fill the suggestion's SELL price, not stay empty and not reuse the buy price.
    fc.chatboxInput.text = "";
    fc.offerCreationType = 1; // selling
    fc.offerContainer.children.get(20).text = "Sell offer";
    fill.invoke(handler);
    check("65*".equals(fc.chatboxInput.text), "Hotkey must fill the exact suggested sell price while selling the same item");

    // A suggestion with no usable sell price (e.g. a malformed 0) must not fill anything while selling.
    fc.chatboxInput.text = "";
    cache.set(suggestion(1, "buy", 100, 50, 0));
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must not fill a non-positive sell price");

    // No cached suggestion at all: never touches the input widget.
    cache.set(null);
    fc.offerCreationType = 0;
    fc.offerContainer.children.get(20).text = "Buy offer";
    fc.chatboxTitle.text = "How many do you wish to buy?";
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must do nothing with no cached suggestion");

    // -- GEOffer.resolveOpenSuggestion: prefers the ranked pick when it matches the item currently
    // open, falls back to a plain OpenItemPriceCache price when only that matches, null otherwise.
    // This is what lets the hint/hotkey work for ANY item being traded, not only EVI's current #1
    // suggestion (the original limitation reported: an item with no reviewed history, or one that
    // simply wasn't the single top-ranked pick, got no hint and filled nothing at all). --
    check(geOffer.resolveOpenSuggestion(null, null) == null, "resolveOpenSuggestion: neither known: null");
    fc.currentItemId = 1;
    check(geOffer.resolveOpenSuggestion(suggestion(1, "buy", 100, 50, 65), openItemPrice(1, 40, 55)).source != null,
      "resolveOpenSuggestion: the ranked pick is preferred over the open-item price when both match the open item");
    check(geOffer.resolveOpenSuggestion(suggestion(2, "buy", 100, 50, 65), openItemPrice(1, 40, 55)).quantity == 0,
      "resolveOpenSuggestion: falls back to the open-item price when the ranked pick doesn't match the open item");
    check(geOffer.resolveOpenSuggestion(suggestion(2, "buy", 100, 50, 65), openItemPrice(3, 40, 55)) == null,
      "resolveOpenSuggestion: null when neither known suggestion matches the open item");

    // End-to-end via the hotkey: no ranked suggestion at all for this item, but a plain live
    // open-item price is known for it -- the price must still fill, but a quantity (always 0 for
    // an open-item price -- there's no track record to size one by) must never be offered/filled.
    cache.set(null);
    openItemPriceCache.set(openItemPrice(1, 42, 58));
    fc.currentItemId = 1;
    fc.offerCreationType = 0;
    fc.chatboxTitle.text = "How many do you wish to buy?";
    fc.chatboxInput.text = "";
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must never fill a quantity for a plain open-item price");
    fc.chatboxTitle.text = "Set a price for each item:";
    fc.offerContainer.children.get(20).text = "Buy offer";
    fill.invoke(handler);
    check("42*".equals(fc.chatboxInput.text), "Hotkey must fill the open-item buy price for an item with no ranked suggestion");
    fc.chatboxInput.text = "";
    fc.offerCreationType = 1;
    fc.offerContainer.children.get(20).text = "Sell offer";
    fill.invoke(handler);
    check("58*".equals(fc.chatboxInput.text), "Hotkey must fill the open-item sell price for an item with no ranked suggestion");
    openItemPriceCache.set(null);
    fc.offerCreationType = 0;
    fc.offerContainer.children.get(20).text = "Buy offer";

    // The keybind listener itself must never treat Enter as the configured hotkey, even if somehow bound to it.
    EviLiveConfig config = (EviLiveConfig) Proxy.newProxyInstance(EviLiveConfig.class.getClassLoader(), new Class[]{EviLiveConfig.class},
      (p, m, a) -> "suggestionKeybind".equals(m.getName()) ? new ModifierlessKeybind(KeyEvent.VK_ENTER, 0) : null);
    SuggestionKeybindHandler enterBound = new SuggestionKeybindHandler(null, null, client, geOffer, cache, openItemPriceCache, config);
    Field listenerField = SuggestionKeybindHandler.class.getDeclaredField("listener"); listenerField.setAccessible(true);
    Object listener = listenerField.get(enterBound);
    Method keyPressed = listener.getClass().getMethod("keyPressed", KeyEvent.class);
    cache.set(suggestion(1, "buy", 100, 50, 65));
    fc.currentItemId = 1;
    fc.offerCreationType = 0; // buying, so the buy price is the one that could get filled
    fc.chatboxTitle.text = "Set a price for each item:";
    fc.offerContainer.children.get(20).text = "Buy offer";
    fc.chatboxInput.text = "";
    // A plain Component (not Label/Button/etc.) never touches a native peer, so this stays safe
    // under java.awt.headless=true, which this Gradle task sets the same way panelTest does.
    java.awt.Component dummy = new java.awt.Component() { };
    KeyEvent enterEvent = new KeyEvent(dummy, KeyEvent.KEY_PRESSED, System.currentTimeMillis(), 0, KeyEvent.VK_ENTER, KeyEvent.CHAR_UNDEFINED);
    // clientThread is null in this handler, so if Enter were not excluded first, the invokeLater
    // call below would throw immediately (synchronously, from within keyPressed) instead of quietly
    // returning; either way nothing gets filled.
    keyPressed.invoke(listener, enterEvent);
    check(fc.chatboxInput.text.isEmpty(), "Enter must never be treated as the fill hotkey even if configured that way");

    System.out.println("PASS: no-slot, wrong-prompt, quantity fill, item mismatch, buy price fill, sell price fill, non-positive sell price, no-suggestion, resolveOpenSuggestion precedence/fallback/null, open-item price fill without a fabricated quantity, and Enter-key exclusion");
  }
}

package com.evi.live;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/** Synthetic transport only. Does not connect to the user's bridge. */
public final class EviLiveDeliveryTest {
  static void set(Object target,String name,Object value)throws Exception {
    Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);field.set(target,value);
  }
  static Object get(Object target,String name)throws Exception {
    Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(target);
  }
  static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
  /** A plugin whose inventory reports exactly these many coins (995) and platinum tokens (13204),
   *  so refreshCashStack can be exercised without a real client. */
  static EviLivePlugin pluginHolding(int coins,int plat) throws Exception {
    java.lang.reflect.InvocationHandler container=(pr,m,ar)->
      m.getName().equals("count") ? (Integer.valueOf(995).equals(ar[0]) ? coins : Integer.valueOf(13204).equals(ar[0]) ? plat : 0) : null;
    java.lang.reflect.InvocationHandler cl=(pr,m,ar)->m.getName().equals("getItemContainer")
      ?java.lang.reflect.Proxy.newProxyInstance(net.runelite.api.ItemContainer.class.getClassLoader(),new Class[]{net.runelite.api.ItemContainer.class},container):null;
    EviLivePlugin p=new EviLivePlugin();
    set(p,"client",java.lang.reflect.Proxy.newProxyInstance(net.runelite.api.Client.class.getClassLoader(),new Class[]{net.runelite.api.Client.class},cl));
    return p;
  }
  static final class Fake implements LocalTransport {
    int code=200;boolean fail;List<String> bodies=new ArrayList<>();
    public int send(String key,String json)throws IOException {
      bodies.add(json);if(fail)throw new IOException("synthetic disconnect");return code;
    }
    public String get(String key,String query)throws IOException {return null;}
  }
  @SuppressWarnings("unchecked")
  public static void main(String[] args)throws Exception {
    EviLivePlugin plugin=new EviLivePlugin();Fake fake=new Fake();
    // gson is @Inject-only on the real plugin (Guice supplies the client's shared instance; the
    // Hub's packager rejects a plugin that constructs its own) -- this harness builds the plugin
    // with `new`, not Guice, so it has to seed the field itself, same as every other @Inject field
    // this file sets via reflection below.
    set(plugin,"gson",new Gson());
    set(plugin,"transport",fake);set(plugin,"running",true);set(plugin,"lifecycle",1L);
    set(plugin,"pluginKey","abcdef0123456789".repeat(4));
    ArrayDeque<String> queue=(ArrayDeque<String>)get(plugin,"queue");
    Method flush=EviLivePlugin.class.getDeclaredMethod("flush",long.class);flush.setAccessible(true);
    queue.add("synthetic-packet-one");fake.code=401;flush.invoke(plugin,1L);
    check(queue.size()==1,"Wrong key must retain pending packet");
    fake.code=200;fake.fail=true;flush.invoke(plugin,1L);
    check(queue.size()==1,"Disconnect must retain pending packet");
    fake.fail=false;flush.invoke(plugin,1L);
    check(queue.isEmpty(),"Successful retry must remove packet");
    check(fake.bodies.size()==3&&fake.bodies.stream().allMatch("synthetic-packet-one"::equals),"Retries must be byte-identical");
    queue.add("new-session-packet");set(plugin,"lifecycle",2L);flush.invoke(plugin,1L);
    check(queue.size()==1&&fake.bodies.size()==3,"Old sender generation must not send new session data");
    set(plugin,"running",false);flush.invoke(plugin,2L);
    check(queue.size()==1&&fake.bodies.size()==3,"Disabled plugin must not deliver");
    set(plugin,"running",true);
    set(plugin,"transport",new LocalTransport(){
      public int send(String key,String json)throws IOException {
        try {
          set(plugin,"pairingRevision",1L);
          queue.clear();queue.add("re-paired-session-packet");
        }catch(Exception ex){throw new IOException(ex);}
        return 200;
      }
      public String get(String key,String query)throws IOException {return null;}
    });
    flush.invoke(plugin,2L);
    check(queue.size()==1&&"re-paired-session-packet".equals(queue.peek()),"Old pairing response must not consume replacement pairing queue");
    queue.clear();for(int i=0;i<512;i++)queue.add("queued-"+i);
    set(plugin,"account","synthetic-account");set(plugin,"session","old-session");
    Method enqueue=EviLivePlugin.class.getDeclaredMethod("enqueue",boolean.class);enqueue.setAccessible(true);enqueue.invoke(plugin,false);
    check(queue.isEmpty()&&get(plugin,"account")==null&&!"old-session".equals(get(plugin,"session")),"Queue overflow must clear unsafe coverage and create a new baseline");

    // suggestionQuery()/sanitizeBlocklist(): built entirely from local config, never from observed
    // content, and must round-trip cleanly to the query string the bridge actually parses.
    Method sanitize=EviLivePlugin.class.getDeclaredMethod("sanitizeBlocklist",String.class);sanitize.setAccessible(true);
    check("4151,995,200".equals(sanitize.invoke(null,"4151, 995,,abc,-3, 200")),"sanitizeBlocklist must trim, drop empty/non-numeric/negative entries, and keep valid IDs in order");
    check("".equals(sanitize.invoke(null,"")),"sanitizeBlocklist must return empty for an empty blocklist");
    check("".equals(sanitize.invoke(null,(Object)null)),"sanitizeBlocklist must return empty for a null blocklist");

    Method suggestionQuery=EviLivePlugin.class.getDeclaredMethod("suggestionQuery");suggestionQuery.setAccessible(true);
    Method resetMethod=EviLivePlugin.class.getDeclaredMethod("reset");resetMethod.setAccessible(true);
    // marginSafetyCushion briefly defaulted to ON, which blocked every live candidate and left the
    // player with no suggestion at all (see EviLiveConfig's own doc). It's back to off by default
    // like every other setting here, so an untouched config sends an empty query again. The
    // explicit marginSafetyCushion(){return false;} overrides in the tests below predate that and
    // are now redundant, but still pin those tests to "cushion off" whatever the default becomes.
    EviLivePlugin defaults=new EviLivePlugin();
    set(defaults,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}});
    check("".equals(suggestionQuery.invoke(defaults)),"With the trade-size cap turned off, an otherwise-untouched config must send an empty query");
    Method cushionItem=EviLiveConfig.class.getDeclaredMethod("marginSafetyCushion");
    check("requireMarginAboveNoise".equals(cushionItem.getAnnotation(net.runelite.client.config.ConfigItem.class).keyName()),"marginSafetyCushion must use its new keyName, so a 'true' RuneLite stored under the old on-by-default key is not picked up");

    EviLivePlugin tuned=new EviLivePlugin();
    set(tuned,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public MinProfitTier minProfitThreshold(){return MinProfitTier.T500K;}
      public boolean marginSafetyCushion(){return false;}
      public String itemBlocklist(){return "4151, 995";}
      public RiskLevel riskLevel(){return RiskLevel.HIGH;}
      public boolean includeMarketSuggestions(){return true;}
      public TradePace tradePace(){return TradePace.FAST;}
    });
    check("minProfit=500000&blocklist=4151,995&risk=high&includeMarket=1&duration=120".equals(suggestionQuery.invoke(tuned)),"All five settings must appear in the query string when set, includeMarket then duration last (cushion disabled here so this test stays about exactly those five)");

    // MinProfitTier: replaces the old free-form gp field with plain preset tiers, AUTO meaning
    // "any profit, no floor" -- must behave exactly like the old default of 0 (left off the query
    // entirely), and each tier must send its own documented gp figure.
    EviLivePlugin autoTier=new EviLivePlugin();
    set(autoTier,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public MinProfitTier minProfitThreshold(){return MinProfitTier.AUTO;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("".equals(suggestionQuery.invoke(autoTier)),"AUTO (the default tier) must be left off the query entirely, same as the old free-form field's 0");

    EviLivePlugin t100k=new EviLivePlugin();
    set(t100k,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public MinProfitTier minProfitThreshold(){return MinProfitTier.T100K;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("minProfit=100000".equals(suggestionQuery.invoke(t100k)),"T100K alone, with no leading '&', when it's the only tuned setting");

    EviLivePlugin t200k=new EviLivePlugin();
    set(t200k,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public MinProfitTier minProfitThreshold(){return MinProfitTier.T200K;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("minProfit=200000".equals(suggestionQuery.invoke(t200k)),"T200K's gp figure");

    EviLivePlugin t1m=new EviLivePlugin();
    set(t1m,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public MinProfitTier minProfitThreshold(){return MinProfitTier.T1M;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("minProfit=1000000".equals(suggestionQuery.invoke(t1m)),"T1M's gp figure");

    EviLivePlugin t2m=new EviLivePlugin();
    set(t2m,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public MinProfitTier minProfitThreshold(){return MinProfitTier.T2M;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("minProfit=2000000".equals(suggestionQuery.invoke(t2m)),"T2M's gp figure");

    // marginSafetyCushion: off by default (see the `defaults` test above); explicitly disabling it
    // must leave the query exactly as before this setting existed, and turning it on must combine
    // with a profit tier in the documented order (minProfit=, then cushion=1, then everything else).
    EviLivePlugin cushionExplicitOff=new EviLivePlugin();
    set(cushionExplicitOff,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("".equals(suggestionQuery.invoke(cushionExplicitOff)),"Explicit marginSafetyCushion=false must be left off the query, matching pre-existing behaviour");

    EviLivePlugin cushionWithTier=new EviLivePlugin();
    set(cushionWithTier,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public MinProfitTier minProfitThreshold(){return MinProfitTier.T500K;}
      public boolean marginSafetyCushion(){return true;}
    });
    check("minProfit=500000&cushion=1".equals(suggestionQuery.invoke(cushionWithTier)),"A profit tier plus an opted-in cushion must both appear, minProfit= before cushion=1");

    EviLivePlugin noDurationPreference=new EviLivePlugin();
    set(noDurationPreference,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public TradePace tradePace(){return TradePace.NONE;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("".equals(suggestionQuery.invoke(noDurationPreference)),"Explicit NONE (no preference) must be left off the query, matching the default");

    EviLivePlugin durationOnly=new EviLivePlugin();
    set(durationOnly,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public TradePace tradePace(){return TradePace.MEDIUM;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("duration=360".equals(suggestionQuery.invoke(durationOnly)),"duration alone, with no leading '&', when it's the only tuned setting");
    // Every pace sends the minutes measured to actually complete a round trip: see TradePace's own
    // doc and tools/hold-length.mjs. Nothing under two hours is offered, because nothing under two
    // hours ever finished one.
    int[] paceMinutes={120,360,720,2880};TradePace[] paces={TradePace.FAST,TradePace.MEDIUM,TradePace.OVERNIGHT,TradePace.SLOW};
    for(int i=0;i<paces.length;i++){
      final TradePace p=paces[i];
      EviLivePlugin longTrade=new EviLivePlugin();
      set(longTrade,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}public TradePace tradePace(){return p;}});
      check(("duration="+paceMinutes[i]).equals(suggestionQuery.invoke(longTrade)),"Each trade pace must send its own minutes: "+p);
      check(p.minutes()>=120,"No pace may promise less than two hours, which never completed: "+p);
    }
    // Where a suggestion may come from. The default is what EVI always did, so it sends nothing.
    for(SuggestionSource src:SuggestionSource.values()){
      final SuggestionSource v=src;
      EviLivePlugin p=new EviLivePlugin();
      set(p,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
        public SuggestionSource suggestionSource(){return v;}
        public boolean marginSafetyCushion(){return false;}
      });
      String q=(String)suggestionQuery.invoke(p);
      if(v==SuggestionSource.HISTORY_FIRST)check("".equals(q),"The default source must add nothing to the query: "+q);
      else check(("source="+v.param()).equals(q),"Each source must send its own value: "+v+" -> "+q);
    }
    // The old setting is hidden and must no longer reach the query, whatever it still holds.
    EviLivePlugin staleDuration=new EviLivePlugin();
    set(staleDuration,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public TradeDuration tradeDuration(){return TradeDuration.FIVE;}
      public boolean marginSafetyCushion(){return false;}
    });
    check("".equals(suggestionQuery.invoke(staleDuration)),"A value left in the retired duration setting must have no effect at all");
    // AUTO leaves the floor to the bridge (which applies a small one); NONE asks for none at all.
    EviLivePlugin noFloor=new EviLivePlugin();
    set(noFloor,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public MinProfitTier minProfitThreshold(){return MinProfitTier.NONE;}
