    EviLivePlugin.AcceptRequest acceptRequest=new EviLivePlugin.AcceptRequest("abc-9-00",9,true);
    check("abc-9-00".equals(acceptRequest.id) && acceptRequest.itemId==9 && acceptRequest.accepted,
      "The accept request must carry the bridge's own suggestion id, the item, and the accepted flag");

    // flagPersonalUse(): the sidebar's "Mark as personal use" button callback. The session-local
    // effects (skippedItemIds, clearing any live heldForResale entry, clearing suggestionCache) run
    // synchronously before the bridge POST/re-poll is handed to the (here, null -- startUp() never
    // ran) sender executor, so they're directly observable without needing a real executor.
    Method flagMethod=EviLivePlugin.class.getDeclaredMethod("flagPersonalUse");flagMethod.setAccessible(true);

    EviLivePlugin buyFlagPlugin=new EviLivePlugin();
    SuggestionCache buyFlagCache=new SuggestionCache();
    set(buyFlagPlugin,"suggestionCache",buyFlagCache);
    buyFlagCache.set(EviLiveSuggestionTest.suggestion(11,"buy",100,10,20));
    flagMethod.invoke(buyFlagPlugin); // a "buy" suggestion has nothing to mark
    check(buyFlagCache.get()!=null,"Personal use on a \"buy\" suggestion must not clear or otherwise touch the cache");
    @SuppressWarnings("unchecked")
    java.util.Set<Integer> buyFlagSkips=(java.util.Set<Integer>)get(buyFlagPlugin,"skippedItemIds");
    check(buyFlagSkips.isEmpty(),"Personal use on a \"buy\" suggestion must not add anything to skippedItemIds");

    EviLivePlugin noBuyIdFlagPlugin=new EviLivePlugin();
    SuggestionCache noBuyIdCache=new SuggestionCache();
    set(noBuyIdFlagPlugin,"suggestionCache",noBuyIdCache);
    // A sell suggestion with no buyId is the idle-inventory tier: gear EVI only sees in the inventory
    // and never watched being bought (a Masori body (f) worn while training Slayer, reported live).
    // There is no purchase to mark, so the ITEM is excluded instead -- before this the button refused
    // to mark anything and the same suggestion came straight back on the next poll.
    Suggestion sellNoBuyId=EviLiveSuggestionTest.suggestion(12,"sell",50,10,20); // buyId left null
    noBuyIdCache.set(sellNoBuyId);
    flagMethod.invoke(noBuyIdFlagPlugin);
    check(noBuyIdCache.get()==null,"Personal use on owned gear must clear the cache, so the same suggestion cannot return");
    @SuppressWarnings("unchecked")
    java.util.Set<Integer> noBuyIdSkips=(java.util.Set<Integer>)get(noBuyIdFlagPlugin,"skippedItemIds");
    check(noBuyIdSkips.contains(12),"Personal use on owned gear must exclude that item for this session too");
    // The request body carries the item instead of a buy, which is what the bridge keys the exclusion by.
    EviLivePlugin.PersonalUseRequest itemRequest=EviLivePlugin.PersonalUseRequest.forItem(12);
    check(itemRequest.buyId==null && itemRequest.itemId!=null && itemRequest.itemId==12 && itemRequest.personal,
      "An owned-gear exclusion must send itemId with no buyId");

    EviLivePlugin flagPlugin=new EviLivePlugin();
    SuggestionCache flagCache=new SuggestionCache();
    set(flagPlugin,"suggestionCache",flagCache);
    Suggestion heldSuggestion=EviLiveSuggestionTest.suggestion(13,"sell",25,10,20);heldSuggestion.buyId="buy-99";
    flagCache.set(heldSuggestion);
    Map<Integer,EviLivePlugin.Held> flagHeld=(Map<Integer,EviLivePlugin.Held>)get(flagPlugin,"heldForResale");
    flagHeld.put(13,new EviLivePlugin.Held(13,25,"Test item","buy-99",0));
    flagMethod.invoke(flagPlugin); // sender is null here (startUp() never ran): must not throw
    @SuppressWarnings("unchecked")
    java.util.Set<Integer> flagSkips=(java.util.Set<Integer>)get(flagPlugin,"skippedItemIds");
    check(flagSkips.contains(13),"Marking personal use must add the item to skippedItemIds, same as a manual skip");
    check(flagCache.get()==null,"Marking personal use must clear the cache immediately so the panel doesn't show stale text");
    check(!flagHeld.containsKey(13),"Marking personal use must clear any live heldForResale entry for the item too");

    check("{\"buyId\":\"buy-99\",\"personal\":true}".equals(new Gson().toJson(new EviLivePlugin.PersonalUseRequest("buy-99"))),
      "PersonalUseRequest's JSON shape must match what the bridge's POST /api/suggestion/personal-use expects");

    // flagNotHeld(): the sidebar's "I don't have this anymore" button -- the in-game counterpart of
    // the scanner's "Still held" close buttons, for a reminder about stock that was used in-game or
    // sold while EVI wasn't watching. Same gating and same immediate session-local effects as
    // flagPersonalUse above; the difference is only which bridge endpoint it posts to.
    Method notHeldMethod=EviLivePlugin.class.getDeclaredMethod("flagNotHeld");notHeldMethod.setAccessible(true);

    EviLivePlugin buyNotHeldPlugin=new EviLivePlugin();
    SuggestionCache buyNotHeldCache=new SuggestionCache();
    set(buyNotHeldPlugin,"suggestionCache",buyNotHeldCache);
    buyNotHeldCache.set(EviLiveSuggestionTest.suggestion(21,"buy",100,10,20));
    notHeldMethod.invoke(buyNotHeldPlugin); // nothing held yet on a "buy" suggestion
    check(buyNotHeldCache.get()!=null,"\"I don't have this anymore\" on a buy suggestion must not clear the cache");
    @SuppressWarnings("unchecked")
    java.util.Set<Integer> buyNotHeldSkips=(java.util.Set<Integer>)get(buyNotHeldPlugin,"skippedItemIds");
    check(buyNotHeldSkips.isEmpty(),"\"I don't have this anymore\" on a buy suggestion must not skip anything");

    EviLivePlugin notHeldPlugin=new EviLivePlugin();
    SuggestionCache notHeldCache=new SuggestionCache();
    set(notHeldPlugin,"suggestionCache",notHeldCache);
    Suggestion staleHolding=EviLiveSuggestionTest.suggestion(22,"sell",2241,2000,2200);staleHolding.buyId="buy-77";staleHolding.persisted=true;
    notHeldCache.set(staleHolding);
    Map<Integer,EviLivePlugin.Held> notHeldHeld=(Map<Integer,EviLivePlugin.Held>)get(notHeldPlugin,"heldForResale");
    notHeldHeld.put(22,new EviLivePlugin.Held(22,2241,"Blue dragon leather","buy-77",2162));
    notHeldMethod.invoke(notHeldPlugin); // sender is null here (startUp() never ran): must not throw
    @SuppressWarnings("unchecked")
    java.util.Set<Integer> notHeldSkips=(java.util.Set<Integer>)get(notHeldPlugin,"skippedItemIds");
    check(notHeldSkips.contains(22),"\"I don't have this anymore\" must skip the item for the rest of the session too");
    check(notHeldCache.get()==null,"\"I don't have this anymore\" must clear the cache immediately");
    check(!notHeldHeld.containsKey(22),"\"I don't have this anymore\" must clear any live heldForResale entry for the item");

    check("{\"buyId\":\"buy-77\",\"reason\":\"sold-untracked\"}".equals(new Gson().toJson(new EviLivePlugin.NotHeldRequest("buy-77"))),
      "NotHeldRequest's JSON shape must match what the bridge's POST /api/suggestion/not-held expects");

    // verifyPersistedHolding(): a "persisted" suggestion (the bridge's restart-safe reconstruction
    // from journaled GE offers, see Suggestion.persisted's own doc) must be checked against the
    // player's actual current inventory before being trusted -- a stale reconstruction (e.g. an
    // old position that was, in reality, fully resold through separate sales the automatic
    // matcher didn't perfectly reconcile) must never sit there forever crowding out a real,
    // currently-held item behind it. This is exactly the failure reported live: an old, already
    // fully-resold blue dragon hide position crowding out the genuinely-still-held eternal boots
    // and zamorak chaps behind it. Exercised entirely through inventoryItemIds/
    // inventorySnapshotEstablished (never through client.getItemContainer() directly): a real
    // client.log confirmed a version of this method that called the Client API from here -- off
    // the background poll thread, not an event-subscriber callback -- threw "AssertionError: must
    // be called on client thread" on every single poll, so this now only ever reads a snapshot
    // that onGameTick refreshes safely from the client thread (see refreshInventoryItemIds).
    Method verify=EviLivePlugin.class.getDeclaredMethod("verifyPersistedHolding",Suggestion.class);verify.setAccessible(true);
    EviLivePlugin verifyPlugin=new EviLivePlugin();
    Suggestion held=EviLiveSuggestionTest.suggestion(5,"sell",2712,1000,1200);held.persisted=true;
    check(((Boolean)verify.invoke(verifyPlugin,held)).booleanValue(),"Before the inventory has ever been successfully snapshotted this session, must fail open (verified), never silently suppress a real reminder");
    set(verifyPlugin,"inventorySnapshotEstablished",true);
    set(verifyPlugin,"inventoryItemIds",java.util.Set.of(5));
    check(((Boolean)verify.invoke(verifyPlugin,held)).booleanValue(),"An item genuinely present in an established inventory snapshot must verify true");
    set(verifyPlugin,"inventoryItemIds",java.util.Set.of());
    check(!((Boolean)verify.invoke(verifyPlugin,held)).booleanValue(),"A confirmed, genuinely empty inventory (e.g. everything banked) must verify false -- it isn't actually held any more");
    set(verifyPlugin,"inventoryItemIds",java.util.Set.of(9));
    check(!((Boolean)verify.invoke(verifyPlugin,held)).booleanValue(),"An established snapshot that simply doesn't contain this item must verify false");

    // correctSellQuantityAgainstInventory(): caps a "sell" suggestion's quantity down to what's
    // actually in the inventory right now -- confirmed against a real report (a partially-filled,
    // later-cancelled buy order left the journal correctly believing 13 were bought and never
    // resold, but only 11 were actually still held).
    Method correct=EviLivePlugin.class.getDeclaredMethod("correctSellQuantityAgainstInventory",Suggestion.class);correct.setAccessible(true);
    EviLivePlugin correctPlugin=new EviLivePlugin();
    correct.invoke(correctPlugin,(Suggestion)null); // must never throw on a null suggestion (pollSuggestion's s can be null)

    Suggestion beforeSnapshot=EviLiveSuggestionTest.suggestion(30810,"sell",13,500000,550000);
    correct.invoke(correctPlugin,beforeSnapshot);
    check(beforeSnapshot.quantity==13,"Before the inventory has ever been successfully snapshotted this session, must fail open -- leave the quantity exactly as the bridge sent it");

    set(correctPlugin,"inventorySnapshotEstablished",true);
    set(correctPlugin,"inventoryQuantities",java.util.Map.of(30810,11));
    Suggestion buySuggestion=EviLiveSuggestionTest.suggestion(30810,"buy",13,500000,550000);
    correct.invoke(correctPlugin,buySuggestion);
    check(buySuggestion.quantity==13,"A \"buy\" suggestion's quantity means something entirely different (how many to acquire) and must never be touched");

    Suggestion overstated=EviLiveSuggestionTest.suggestion(30810,"sell",13,500000,550000);
    correct.invoke(correctPlugin,overstated);
    check(overstated.quantity==11,"An overstated sell quantity must be reduced to what's actually held");
    check(overstated.reasoning.contains("Reduced from 13 to the 11"),"The reduction must be explained in the reasoning text, the same way cash/duration limits already are");

    Suggestion exact=EviLiveSuggestionTest.suggestion(30810,"sell",11,500000,550000);
    correct.invoke(correctPlugin,exact);
    check(exact.quantity==11,"A quantity that already matches what's held must be left unchanged");

    Suggestion understated=EviLiveSuggestionTest.suggestion(30810,"sell",5,500000,550000);
    correct.invoke(correctPlugin,understated);
    check(understated.quantity==5,"A quantity LOWER than what's actually held must never be increased -- there could be older stock this suggestion isn't even about");

    Suggestion unknownItem=EviLiveSuggestionTest.suggestion(9999,"sell",7,500000,550000);
    correct.invoke(correctPlugin,unknownItem);
    check(unknownItem.quantity==7,"An item with no entry at all in the inventory snapshot (not what this correction is for) must be left alone, not zeroed out");

    // pollSuggestion(): a persisted suggestion the inventory check rejects must be auto-skipped
    // (same effect as the manual "Skip this suggestion" button above) and re-polled, never cached
    // or shown to the player.
    Method poll=EviLivePlugin.class.getDeclaredMethod("pollSuggestion",long.class);poll.setAccessible(true);
    EviLivePlugin pollPlugin=new EviLivePlugin();
    set(pollPlugin,"gson",new Gson());
    set(pollPlugin,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;} // suggestionQuery() (called at the top of every real pollSuggestion()) needs this
      public boolean marginSafetyCushion(){return false;}
    });
    set(pollPlugin,"running",true);set(pollPlugin,"lifecycle",1L);
    set(pollPlugin,"pluginKey","abcdef0123456789".repeat(4));
    set(pollPlugin,"inventorySnapshotEstablished",true);
    set(pollPlugin,"inventoryItemIds",java.util.Set.of()); // established, empty: item 5 is not actually held
    set(pollPlugin,"transport",new LocalTransport(){
      public int send(String key,String json)throws IOException {return 200;}
      public String get(String key,String query)throws IOException {
        return "{\"suggestion\":{\"itemId\":5,\"name\":\"Blue dragon hide\",\"action\":\"sell\",\"quantity\":2712,\"buyPrice\":1000,\"sellPrice\":1200,\"source\":\"holding\",\"reasoning\":\"stale\",\"persisted\":true}}";
      }
    });
    poll.invoke(pollPlugin,1L); // sender is null here (startUp() never ran): the auto-retry attempt must not throw
    @SuppressWarnings("unchecked")
    java.util.Set<Integer> pollPluginSkips=(java.util.Set<Integer>)get(pollPlugin,"skippedItemIds");
    check(pollPluginSkips.contains(5),"A persisted suggestion for an item genuinely absent from the inventory must be auto-skipped, exactly like a manual skip");
    check(get(pollPlugin,"suggestionCache")==null,"The rejected phantom suggestion must never reach suggestionCache (left uninitialized/untouched in this harness)");

    // The same suggestion, but the item genuinely IS in the inventory: must be trusted and cached
    // normally, exactly as an unpersisted (live-observed) suggestion always has been.
    EviLivePlugin pollPlugin2=new EviLivePlugin();
    set(pollPlugin2,"gson",new Gson());
    set(pollPlugin2,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public boolean marginSafetyCushion(){return false;}
    });
    set(pollPlugin2,"running",true);set(pollPlugin2,"lifecycle",1L);
    set(pollPlugin2,"pluginKey","abcdef0123456789".repeat(4));
    set(pollPlugin2,"suggestionCache",new SuggestionCache());
    set(pollPlugin2,"openItemPriceCache",new OpenItemPriceCache());
    set(pollPlugin2,"inventorySnapshotEstablished",true);
    set(pollPlugin2,"inventoryItemIds",java.util.Set.of(5)); // genuinely still held
    set(pollPlugin2,"transport",new LocalTransport(){
      public int send(String key,String json)throws IOException {return 200;}
      public String get(String key,String query)throws IOException {
        return "{\"suggestion\":{\"itemId\":5,\"name\":\"Blue dragon hide\",\"action\":\"sell\",\"quantity\":2712,\"buyPrice\":1000,\"sellPrice\":1200,\"source\":\"holding\",\"reasoning\":\"real\",\"persisted\":true}}";
      }
    });
    poll.invoke(pollPlugin2,1L);
    SuggestionCache resultCache=(SuggestionCache)get(pollPlugin2,"suggestionCache");
    check(resultCache.get()!=null && resultCache.get().itemId==5,"A persisted suggestion for an item genuinely still in the inventory must be cached and shown normally");
    @SuppressWarnings("unchecked")
    java.util.Set<Integer> pollPlugin2Skips=(java.util.Set<Integer>)get(pollPlugin2,"skippedItemIds");
    check(pollPlugin2Skips.isEmpty(),"A verified-real persisted suggestion must not be skipped");

    // pollSuggestion() end-to-end: the bridge's remembered quantity (13, matching the journal) is
    // higher than what's actually in the inventory right now (11) -- the exact in-game shape of
    // the bug report this fix came from (a partially-filled buy order, cancelled, left a stale
    // remaining count). Must come through corrected, not as the bridge originally sent it.
    EviLivePlugin pollPlugin3=new EviLivePlugin();
    set(pollPlugin3,"gson",new Gson());
    set(pollPlugin3,"config",new EviLiveConfig(){public MaxTradeShare maxTradeShare(){return MaxTradeShare.OFF;}public TradingProfile tradingProfile(){return TradingProfile.STANDARD;}
      public boolean marginSafetyCushion(){return false;}
    });
    set(pollPlugin3,"running",true);set(pollPlugin3,"lifecycle",1L);
    set(pollPlugin3,"pluginKey","abcdef0123456789".repeat(4));
    set(pollPlugin3,"suggestionCache",new SuggestionCache());
    set(pollPlugin3,"openItemPriceCache",new OpenItemPriceCache());
    set(pollPlugin3,"inventorySnapshotEstablished",true);
    set(pollPlugin3,"inventoryItemIds",java.util.Set.of(30810)); // genuinely still held, just not 13 of it
    set(pollPlugin3,"inventoryQuantities",java.util.Map.of(30810,11));
    set(pollPlugin3,"transport",new LocalTransport(){
      public int send(String key,String json)throws IOException {return 200;}
      public String get(String key,String query)throws IOException {
        return "{\"suggestion\":{\"itemId\":30810,\"name\":\"Contract of glyphic attenuation\",\"action\":\"sell\",\"quantity\":13,\"buyPrice\":500000,\"sellPrice\":550000,\"source\":\"holding\",\"reasoning\":\"You're holding 13 from an earlier buy\",\"persisted\":true}}";
      }
    });
    poll.invoke(pollPlugin3,1L);
    Suggestion corrected=((SuggestionCache)get(pollPlugin3,"suggestionCache")).get();
    check(corrected!=null && corrected.quantity==11,"pollSuggestion must apply the inventory correction before caching, not just verify presence");
    check(corrected.reasoning.contains("Reduced from 13 to the 11"),"The corrected suggestion's reasoning must explain the reduction");

    // Settings panel: each description is a hover tooltip. The user reported the old ones -- some
    // over 700 characters -- as unreadable, so they are held to one short sentence here.
    java.util.Set<String> keyNames=new java.util.TreeSet<>();
    for(Method m:EviLiveConfig.class.getDeclaredMethods()) {
      net.runelite.client.config.ConfigItem item=m.getAnnotation(net.runelite.client.config.ConfigItem.class);
      if(item==null)continue;
      keyNames.add(item.keyName());
      check(item.description().length()<=110,"Tooltip for \""+item.name()+"\" is "+item.description().length()+" characters; keep it to one short sentence (110 max)");
      check(!item.description().isEmpty(),"Every visible setting needs a tooltip: "+item.name());
    }
    // RuneLite stores settings by keyName, so renaming one silently resets that setting for every
    // existing user. Changing names and tooltips is safe; this list must only ever grow.
    check(keyNames.equals(new java.util.TreeSet<>(java.util.Arrays.asList(
      "suggestionKeybind","showSuggestionHint","minProfitTier","itemBlocklist","riskLevel","includeMarketSuggestions",
      "tradingProfile","maxTradeShare","tradeDuration","tradePace","suggestionSource","suggestIdleInventory","forecastHorizon","forecastPolicy","requireMarginAboveNoise","panelTheme","suggestionFocus",
      "maxPositions","positionSizing"))),
      "A setting's keyName changed or disappeared, which would reset it for existing users: "+keyNames);

    // A rejected key and an unreachable bridge both arrive as a null body, and they need opposite
    // advice. EVI's second user was shown "Bridge unreachable" beside "Bridge rejected the key" in
    // the same panel while their companion app was running perfectly -- they had pasted the Scanner
    // key. Sending someone to check the thing that is not wrong is the worst kind of error message.
    // ...and the field has to come BACK, or the advice is unusable. The pairing section was hidden
    // whenever a key had been SAVED, not when one had been accepted, so a mistyped key took the
    // field, the Save button and the whole section away -- leaving no way to correct it short of
    // deleting plugin-key.txt from .runelite/plugin-data/evi-live, which no player should be told.
    String saved="abcdef0123456789".repeat(4);
    check(EviLivePlugin.showAsPaired(saved,false),"A saved key the bridge accepts hides the pairing field");
    check(!EviLivePlugin.showAsPaired(saved,true),"A saved key the bridge REFUSES must bring the field back -- otherwise there is nowhere to paste the right one");
    check(!EviLivePlugin.showAsPaired(null,false),"No key at all means the field stays visible");
    check(!EviLivePlugin.showAsPaired("",false),"An empty key is not a pairing");

    String wrongKey=EviLivePlugin.bridgeFailureMessage(401);
    check(wrongKey.contains("RuneLite plugin key"),"A 401 must name WHICH key to paste: "+wrongKey);
    check(wrongKey.contains("Scanner key"),"A 401 must name the wrong key too, since the two print on adjacent lines: "+wrongKey);
    check(!wrongKey.contains("unreachable"),"A 401 is the bridge ANSWERING -- it must never be called unreachable: "+wrongKey);
    for(int st:new int[]{0,500,404,200}) {
      String other=EviLivePlugin.bridgeFailureMessage(st);
      check(other.contains("unreachable"),"Status "+st+" cannot be blamed on the key -- it may genuinely be unreachable: "+other);
      check(!other.contains("Wrong key"),"Only a 401 may be reported as a wrong key, not status "+st);
    }

    System.out.println("PASS: authentication failure, disconnect, exact retry, stale sender, disabled delivery, pairing replacement, overflow rebaseline, the suggestion-settings query builder (including target trade duration), the cash-stack query building, the open-offer-item query building, the held-for-resale query building (including the held item's own buy offerId), the active-slot/skip exclude query building, the skip-suggestion and block callbacks (the block request naming the item), the accept-suggestion callback (the pick left on screen and not set aside, the toggle, the no-op without a bridge-issued id, and the AcceptRequest JSON shape), the persisted-suggestion inventory verification, the poll-time auto-skip of a stale persisted suggestion, the personal-use button callback (no-op on a buy suggestion; an item-level exclusion for owned gear the idle-inventory tier offered, with no buy behind it; the session-local exclusion on an actual held item), the PersonalUseRequest JSON shape, the inventory-quantity/idle-inventory-suggestion query building, the sell-quantity correction against actual current inventory (including its end-to-end effect through pollSuggestion), the in-progress-offer slots= query building (item:remainingQty pairs, excluding terminal-but-uncollected offers), the activeOffers snapshot itself (price/direction/name/remaining quantity, terminal offers excluded), the offer-drift cancel/relist hint (buy offers below market, sell offers above market, within-threshold and missing-price cases all left unflagged), the offer fill-time hint (on-pace and no-estimate cases left unflagged, minutes phrased as hours past 60, the -1 no-volume sentinel never printed as a number, and the wording kept to a hedged volume observation rather than a fill guarantee), Held.price/holdBuyPrice (the real spent/filled average paid, correctly rounded, sent only when known, and never fabricated when no spent data was observed), the MinProfitTier preset tiers (AUTO left off the query exactly like the old free-form field's 0, each tier's own gp figure), and marginSafetyCushion (off by default under its new keyName, combining correctly with a profit tier when opted in, and explicit-off matching pre-existing behaviour), the sidebar's full GE offer list snapshot (uncollected offers included, cleared on reset), the no-suggestion message wording, the cash stack counting coins AND platinum tokens at 1,000 gp each without overflowing (a full stack of both is ~2.149 trillion) and reporting -1 rather than 0 when the inventory cannot be read, the 401-versus-unreachable distinction (a rejected key names which of the two printed keys to use and is never called unreachable; every other status keeps the unreachable wording), and the members= world-type parameter, and the focus= parameter from the plugin's own Suggestion focus");
  }
}

package com.evi.live;

import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JButton;
import javax.swing.JPasswordField;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;

/** Exercises sidebar controls without RuneLite login or real key files. */
public final class EviLivePanelTest {
  private static void visit(Container parent,List<Component> result) {
    for(Component child:parent.getComponents()) {
      result.add(child);
      if(child instanceof Container)visit((Container)child,result);
    }
  }
  public static void main(String[] args) throws Exception {
    AtomicReference<EviLivePanel> built=new AtomicReference<>();
    SwingUtilities.invokeAndWait(()->{
      AtomicReference<String> saved=new AtomicReference<>();
      java.util.concurrent.atomic.AtomicInteger skips=new java.util.concurrent.atomic.AtomicInteger();
      java.util.concurrent.atomic.AtomicInteger personalUses=new java.util.concurrent.atomic.AtomicInteger();
      java.util.concurrent.atomic.AtomicInteger notHelds=new java.util.concurrent.atomic.AtomicInteger();
      java.util.concurrent.atomic.AtomicInteger blocks=new java.util.concurrent.atomic.AtomicInteger();
      java.util.concurrent.atomic.AtomicInteger resets=new java.util.concurrent.atomic.AtomicInteger();
      final EviLivePanel panel=new EviLivePanel(saved::set,skips::incrementAndGet,personalUses::incrementAndGet,notHelds::incrementAndGet,blocks::incrementAndGet,resets::incrementAndGet);
      List<Component> components=new ArrayList<>();visit(panel,components);
      JPasswordField field=(JPasswordField)components.stream().filter(x->x instanceof JPasswordField).findFirst().orElseThrow();
      List<JButton> buttons=components.stream().filter(x->x instanceof JButton).map(x->(JButton)x).collect(java.util.stream.Collectors.toList());
      JButton pairButton=buttons.stream().filter(b->"Save pairing key".equals(b.getText())).findFirst().orElseThrow();
      JButton skipButton=buttons.stream().filter(b->"Skip".equals(b.getText())).findFirst().orElseThrow();
      JButton personalUseButton=buttons.stream().filter(b->"Mine".equals(b.getText())).findFirst().orElseThrow();
      String synthetic="abcdef0123456789".repeat(4);
      field.setText(synthetic);pairButton.doClick();
      if(!synthetic.equals(saved.get()))throw new AssertionError("Pairing callback did not receive key");
      if(field.getPassword().length!=0)throw new AssertionError("Pairing input must be cleared after save");
      if(field.getEchoChar()==0)throw new AssertionError("Key input must be masked");
      if(EviLivePanel.icon().getWidth()!=24)throw new AssertionError("Sidebar icon dimensions");
      skipButton.doClick();
      if(skips.get()!=1)throw new AssertionError("Skip callback must fire exactly once per click");
      personalUseButton.doClick();
      if(personalUses.get()!=1)throw new AssertionError("Personal-use callback must fire exactly once per click");
      JButton notHeldButton=buttons.stream().filter(b->"Gone".equals(b.getText())).findFirst().orElseThrow();
      notHeldButton.doClick();
      if(notHelds.get()!=1)throw new AssertionError("Not-held callback must fire exactly once per click");
      // Block: Skip made permanent, so a player can refuse an item without looking up its ID.
      JButton blockButton=buttons.stream().filter(b->"Block".equals(b.getText())).findFirst().orElseThrow(()->new AssertionError("The sidebar needs a Block button"));
      blockButton.doClick();
      if(blocks.get()!=1)throw new AssertionError("Block callback must fire exactly once per click");
      // The profit line and its Reset: asked for so the sidebar shows what EVI has actually realised.
      JButton resetButton=buttons.stream().filter(b->"Reset profit count".equals(b.getText())).findFirst().orElseThrow(()->new AssertionError("The sidebar needs a profit Reset button"));
      resetButton.doClick();
      if(resets.get()!=1)throw new AssertionError("Reset callback must fire exactly once per click");

      // Active offers list: every occupied slot gets its own row, terminal-but-uncollected included.
      EviLivePlugin.OfferRow buying=new EviLivePlugin.OfferRow(0,2,243,4000,11000,true,"Steel cannonball","BUYING");
      EviLivePlugin.OfferRow sold=new EviLivePlugin.OfferRow(3,4151,1500000,1,1,false,"Abyssal whip","SOLD");
      EviLivePlugin.OfferRow cancelled=new EviLivePlugin.OfferRow(5,11,97,0,300,true,"","CANCELLED_BUY");
      panel.renderOffers(List.of(buying,sold,cancelled));
      List<String> labels=labels(panel);
      // Built with the same %,d the panel uses, so the grouping separator follows the machine's locale (e.g. 4.000 on a Dutch system).
      for(String expected:List.of("BUY  Steel cannonball",String.format("%,d / %,d at %,d gp - Buying",4000,11000,243),"SELL  Abyssal whip",String.format("1 / 1 at %,d gp - Sold, collect",1500000),"BUY  item 11","0 / 300 at 97 gp - Cancelled, collect"))
        if(!labels.contains(expected))throw new AssertionError("Active offers list is missing \""+expected+"\"; got "+labels);
      if(EviLivePanel.offerStatus(new EviLivePlugin.OfferRow(1,1,1,0,1,false,"x","CANCELLED_SELL")).equals("Cancelled, collect")==false)throw new AssertionError("CANCELLED_SELL status text");
      panel.renderOffers(List.of());
      if(labels(panel).stream().anyMatch(l->l.startsWith("BUY ")||l.startsWith("SELL ")))throw new AssertionError("An empty offer list must remove every previous row");
      List<Component> afterClear=new ArrayList<>();visit(panel,afterClear);
      if(afterClear.stream().noneMatch(c->c instanceof javax.swing.JTextArea && "No offers in the Grand Exchange.".equals(((javax.swing.JTextArea)c).getText())))throw new AssertionError("An empty offer list must say so");

      // Scrolling: reported from the live client, the sidebar could not stay scrolled to the top
      // because every text area's caret followed each 2-second rewrite and scrolled to it. No
      // sidebar text area may move its caret on an update.
      for(Component c:afterClear) {
        if(!(c instanceof javax.swing.JTextArea))continue;
        javax.swing.text.Caret caret=((javax.swing.JTextArea)c).getCaret();
        if(!(caret instanceof javax.swing.text.DefaultCaret)||((javax.swing.text.DefaultCaret)caret).getUpdatePolicy()!=javax.swing.text.DefaultCaret.NEVER_UPDATE)
          throw new AssertionError("A sidebar text area still moves its caret on update, which scrolls the sidebar: \""+((javax.swing.JTextArea)c).getText()+"\"");
      }
      // And the same text re-sent by the poll must not be rewritten at all.
      javax.swing.JTextArea probe=new javax.swing.JTextArea("same");
      if(EviLivePanel.setIfChanged(probe,"same"))throw new AssertionError("Unchanged text must not be rewritten");
      if(!EviLivePanel.setIfChanged(probe,"different")||!"different".equals(probe.getText()))throw new AssertionError("Changed text must be written");
      if(!EviLivePanel.setIfChanged(probe,null)||!"".equals(probe.getText()))throw new AssertionError("null clears the text rather than throwing");

      built.set(panel);
    });

    // The profit line: the bridge's own matched-flip total, what it leaves out said beside it, and an
    // unreadable answer admitted rather than shown as zero.
    final EviLivePanel profitPanel=built.get();
    EviLivePlugin.Profit p=new EviLivePlugin.Profit();
    p.gp=2020133;p.trades=43;p.winners=30;p.losers=13;p.unmatchedSales=17;p.openPositions=4;
    profitPanel.profit(p);
    SwingUtilities.invokeAndWait(()->{});
    String line=profitText(profitPanel);
    javax.swing.JLabel figure=profitFigure(profitPanel);
    if(figure==null||!("+"+String.format("%,d",2020133)+" gp").equals(figure.getText()))
      throw new AssertionError("The realised figure belongs in its own label: "+(figure==null?"absent":figure.getText()));
    // Green up. Asked for by novi on 29 Sept so the total reads at a glance.
    if(!EviTheme.palette().good.equals(figure.getForeground()))
      throw new AssertionError("A profit must be coloured as one: "+figure.getForeground());
    if(!line.contains("everything EVI has matched"))throw new AssertionError("Without a reset it must say what it covers: "+line);
    if(!line.contains("43 trades: 30 up, 13 down"))throw new AssertionError("Trades and the split belong on the line: "+line);
    if(!line.contains("17 sales EVI never saw bought")||!line.contains("4 purchases not yet sold"))
      throw new AssertionError("What the total leaves out must be stated, never folded in: "+line);
    EviLivePlugin.Profit since=new EviLivePlugin.Profit();
    since.since=1758000000000L;since.gp=-5000;since.trades=1;since.losers=1;
    profitPanel.profit(since);
    SwingUtilities.invokeAndWait(()->{});
    String reset=profitText(profitPanel);
    javax.swing.JLabel lossFigure=profitFigure(profitPanel);
    if(lossFigure==null||!(String.format("%,d",-5000)+" gp").equals(lossFigure.getText()))
      throw new AssertionError("A loss is not dressed up: "+(lossFigure==null?"absent":lossFigure.getText()));
    if(!EviTheme.palette().bad.equals(lossFigure.getForeground()))
      throw new AssertionError("A loss must be coloured as one, never green: "+lossFigure.getForeground());
    if(!reset.startsWith("(since you reset"))throw new AssertionError("A reset count says so: "+reset);
    if(reset.contains("Not counted"))throw new AssertionError("With nothing left out, the caveat must not appear: "+reset);
    profitPanel.profit(null);
    SwingUtilities.invokeAndWait(()->{});
    if(!profitText(profitPanel).contains("Profit unavailable"))throw new AssertionError("An unreadable figure must be admitted, not shown as zero");
    profitPanel.profitResetPending();
    SwingUtilities.invokeAndWait(()->{});
    if(!profitText(profitPanel).contains("Counting from now"))throw new AssertionError("Reset needs immediate feedback while the poll catches up");

    // Colour scheme: switching it repaints the panel in place -- a cosmetic setting that needed a
    // client restart would read as the setting not working. Each step is checked in a later EDT turn,
    // because applyTheme queues its repaint rather than painting inside the caller's own turn.
    EviLivePanel panel=built.get();
    panel.applyTheme(PanelTheme.OLD_SCHOOL);
    panel.offers(java.util.Arrays.asList(new EviLivePlugin.OfferRow(0,2,100,5,10,true,"Test item","BUYING")));
    SwingUtilities.invokeAndWait(()->{
      if(!panel.getBackground().equals(EviTheme.OLD_SCHOOL.background))throw new AssertionError("The panel must repaint in the chosen scheme");
      List<Component> themed=new ArrayList<>();visit(panel,themed);
      if(themed.stream().noneMatch(c->c instanceof javax.swing.JPanel && c.getBackground().equals(EviTheme.OLD_SCHOOL.card)))
        throw new AssertionError("An offer row rebuilt after the switch must use the chosen scheme too");
    });
    panel.applyTheme(PanelTheme.RUNELITE);
    SwingUtilities.invokeAndWait(()->{
      if(!panel.getBackground().equals(EviTheme.RUNELITE.background))throw new AssertionError("Switching back must restore RuneLite's own colours");
    });
    // The suggestion card (layout D). The sidebar used to state a number and bury whether EVI trusted
    // it: a player bought 30 Contract of Glyphic Attenuation expecting the 2,977,560 gp the quoted
    // spread implied, when it was worth about 350,000 -- and EVI had demoted the pick and said so, in
    // the middle of a paragraph. These check that the doubt is now drawn, and that a bridge which sends
    // no verdict still gets the old paragraph.
    Suggestion clear=new Suggestion();
    clear.itemId=28919;clear.name="Tonalztics of Ralos";clear.action="buy";clear.quantity=1;
    clear.buyPrice=47451388;clear.sellPrice=49666111;clear.expectedProfit=1221401L;
    clear.verdict=new Suggestion.Verdict();
    clear.verdict.level="clear";clear.verdict.label="Every check passed";
    clear.verdict.checks=new ArrayList<>();
    Suggestion.Check passed=new Suggestion.Check();passed.ok=Boolean.TRUE;passed.text="Buyers paying more than quoted";
    clear.verdict.checks.add(passed);
    panel.suggestion(clear,"fallback prose that must not be shown");
    SwingUtilities.invokeAndWait(()->{
      List<Component> card=new ArrayList<>();visit(panel,card);
      String all=card.stream().filter(c->c instanceof JTextArea||c instanceof javax.swing.JLabel)
        .map(c->c instanceof JTextArea?((JTextArea)c).getText():((javax.swing.JLabel)c).getText())
        .collect(java.util.stream.Collectors.joining("\n"));
      if(all.contains("fallback prose"))throw new AssertionError("A verdict must replace the paragraph, not sit beside it");
      if(!all.contains("Tonalztics of Ralos"))throw new AssertionError("The card must name the item");
      if(!all.contains("+"+String.format("%,d",1221401L)))throw new AssertionError("The card must lead with what the trade is worth");
      if(!all.contains("BUY "+String.format("%,d",1)))throw new AssertionError("The card must say what it is asking for");
      if(!all.contains("EVERY CHECK PASSED"))throw new AssertionError("The verdict label must show");
      if(!all.contains("Buyers paying more than quoted"))throw new AssertionError("Each check line must show");
    });

    // A flagged pick: the edge, the label and the failing line all have to carry the warning colour,
    // and the failing line needs its own mark -- colour alone is not a distinction everyone can see.
    Suggestion flagged=new Suggestion();
    flagged.itemId=30810;flagged.name="Contract of Glyphic Attenuation";flagged.action="buy";flagged.quantity=30;
    flagged.buyPrice=354488;flagged.sellPrice=463000;flagged.expectedProfit=2977560L;
    flagged.verdict=new Suggestion.Verdict();
    flagged.verdict.level="caution";flagged.verdict.label="Worth less than it looks";
    flagged.verdict.checks=new ArrayList<>();
    Suggestion.Check failed=new Suggestion.Check();failed.ok=Boolean.FALSE;failed.text="349,560 at what buyers really pay";
    flagged.verdict.checks.add(failed);
    panel.suggestion(flagged,"prose");
    SwingUtilities.invokeAndWait(()->{
      List<Component> card=new ArrayList<>();visit(panel,card);
      boolean marked=card.stream().anyMatch(c->c instanceof JTextArea
        && ((JTextArea)c).getText().startsWith("! ")
        && ((JTextArea)c).getText().contains("349,560"));
      if(!marked)throw new AssertionError("A failed check needs a mark of its own, not colour alone");
      boolean warned=card.stream().anyMatch(c->c instanceof javax.swing.JLabel
        && "WORTH LESS THAN IT LOOKS".equals(((javax.swing.JLabel)c).getText())
        && c.getForeground().equals(EviTheme.RUNELITE.warn));
      if(!warned)throw new AssertionError("A cautioned pick must be coloured as one");
    });

    // No verdict -- an older bridge, or a pick nothing was measured about -- falls back to the prose.
    Suggestion bare=new Suggestion();
    bare.itemId=1;bare.name="Thing";bare.action="buy";bare.quantity=1;bare.buyPrice=10;bare.sellPrice=20;
    panel.suggestion(bare,"Thing x1 - buy 10 gp / sell 20 gp");
    SwingUtilities.invokeAndWait(()->{
      List<Component> back=new ArrayList<>();visit(panel,back);
      boolean prose=back.stream().anyMatch(c->c instanceof JTextArea
        && "Thing x1 - buy 10 gp / sell 20 gp".equals(((JTextArea)c).getText()));
      if(!prose)throw new AssertionError("Without a verdict the paragraph must come back");
      boolean leftover=back.stream().anyMatch(c->c instanceof javax.swing.JLabel
        && "Contract of Glyphic Attenuation".equals(((javax.swing.JLabel)c).getText()));
      if(leftover)throw new AssertionError("The previous card must be cleared away, not left underneath");
    });

    // Pairing collapses once a key is held. The sidebar is 225px wide, and setup that is finished is
    // the cheapest thing on it to give up -- but it has to come back if the key is ever cleared, or a
    // player who loses one has no way to enter another.
    panel.paired(true);
    SwingUtilities.invokeAndWait(()->{
      List<Component> after=new ArrayList<>();visit(panel,after);
      boolean fieldShowing=after.stream().anyMatch(c->c instanceof JPasswordField&&c.isShowing());
      if(fieldShowing)throw new AssertionError("A paired sidebar must not keep showing the key field");
      boolean saveShowing=after.stream().anyMatch(c->c instanceof JButton
        &&"Save pairing key".equals(((JButton)c).getText())&&c.isShowing());
      if(saveShowing)throw new AssertionError("The save button goes with it");
    });
    panel.paired(false);
    SwingUtilities.invokeAndWait(()->{
      List<Component> back=new ArrayList<>();visit(panel,back);
      boolean field=back.stream().anyMatch(c->c instanceof JPasswordField&&c.getParent()!=null&&c.getParent().isVisible());
      if(!field)throw new AssertionError("Clearing a key must bring the pairing fields back");
    });
    panel.paired(true);

    // The status line moved to the bottom and carries a dot: green once the bridge has answered.
    panel.status("Connected to the local bridge. Last delivery: 12:00:00");
    SwingUtilities.invokeAndWait(()->{
      List<Component> lit=new ArrayList<>();visit(panel,lit);
      boolean green=lit.stream().anyMatch(c->c instanceof javax.swing.JPanel
        &&c.getBackground()!=null&&c.getBackground().equals(EviTheme.RUNELITE.good));
      if(!green)throw new AssertionError("A connected bridge should show as connected");
    });
    panel.status("Bridge unavailable. Start EVI; queued observations will retry automatically.");
    SwingUtilities.invokeAndWait(()->{
      List<Component> dark=new ArrayList<>();visit(panel,dark);
      boolean warned=dark.stream().anyMatch(c->c instanceof javax.swing.JPanel
        &&c.getBackground()!=null&&c.getBackground().equals(EviTheme.RUNELITE.warn));
      if(!warned)throw new AssertionError("An unreachable bridge must not still look connected");
    });

    // The session's set-aside list, which until 28 Sept 2026 was invisible and one-way. It is fed by
    // four buttons and one automatic path and only ever cleared on a client restart, so a player
    // could work down from a 441,621 gp pick to one worth a few hundred with nothing on screen
    // admitting why. Hidden at zero so it costs nothing until it is actually shaping the answer.
    {
      final int[] cleared={0};
      EviLivePanel sp=new EviLivePanel(k->{},()->{},()->{},()->{},()->{},()->{},()->cleared[0]++);
      sp.skipped(0);SwingUtilities.invokeAndWait(()->{});
      if(labels(sp).stream().anyMatch(t->t!=null&&t.contains("set aside")))
        throw new AssertionError("Nothing set aside must show no line at all");
      sp.skipped(1);SwingUtilities.invokeAndWait(()->{});
      if(labels(sp).stream().noneMatch(t->t!=null&&t.equals("1 item set aside this session")))
        throw new AssertionError("One item must read in the singular: "+labels(sp));
      sp.skipped(7);SwingUtilities.invokeAndWait(()->{});
      if(labels(sp).stream().noneMatch(t->t!=null&&t.equals("7 items set aside this session")))
        throw new AssertionError("The count must be shown: "+labels(sp));
      // And the way back has to actually be reachable and wired.
      List<Component> spAll=new ArrayList<>();visit(sp,spAll);
      javax.swing.JButton back=spAll.stream().filter(c->c instanceof javax.swing.JButton)
        .map(c->(javax.swing.JButton)c).filter(b->"Show skipped items again".equals(b.getText()))
        .findFirst().orElseThrow(()->new AssertionError("No way to undo the session's own filter"));
      if(!back.isVisible())throw new AssertionError("The undo must be visible once something is set aside");
      back.doClick();SwingUtilities.invokeAndWait(()->{});
      if(cleared[0]!=1)throw new AssertionError("The undo button must call back exactly once, got "+cleared[0]);
      sp.skipped(0);SwingUtilities.invokeAndWait(()->{});
      if(back.isVisible())throw new AssertionError("It must disappear again once nothing is set aside");
    }

    System.out.println("PASS: the session set-aside count and its undo button; the profit line (the figure in its own label, coloured green up and red down, trades, what it leaves out, a reset count, an unreadable answer, and reset feedback), the five-icon action row (each caption, its callback, and the row replacing the old button stack), the colour-scheme switch repainting in place (including rows rebuilt afterwards), sidebar pairing callback, masked key input and clearing after save, the skip-suggestion and block button callbacks, the personal-use and not-held button callbacks, the Active offers list (one row per occupied slot including uncollected/cancelled ones, status text, and clearing), the scroll fix (no sidebar text area moves its caret, unchanged text is never rewritten), the suggestion card (item, worth, verdict label and check lines; a failed check marked as well as coloured; and the paragraph coming back when the bridge sends no verdict), and the pairing section collapsing once paired and returning when a key is cleared, with the status dot tracking the bridge");
  }
  /** The profit line's current text: the one text area that starts with a figure or its own status. */
  private static String profitText(Container panel) {
    List<Component> all=new ArrayList<>();visit(panel,all);
    return all.stream().filter(c->c instanceof javax.swing.JTextArea).map(c->((javax.swing.JTextArea)c).getText())
      .filter(t->t.startsWith("(")||t.startsWith("Profit unavailable")||t.startsWith("Counting from now")||t.startsWith("Waiting for the bridge"))
      .findFirst().orElse("");
  }

  /** The realised figure, which is now a bold JLabel of its own so it can carry the up/down colour
   *  without painting the "Not counted" caveats beside it the same shade. */
  private static javax.swing.JLabel profitFigure(Container panel) {
    List<Component> all=new ArrayList<>();visit(panel,all);
    return all.stream().filter(c->c instanceof javax.swing.JLabel).map(c->(javax.swing.JLabel)c)
      .filter(l->l.getText()!=null&&l.getText().endsWith(" gp"))
      .findFirst().orElse(null);
  }

  private static List<String> labels(Container panel) {
    List<Component> all=new ArrayList<>();visit(panel,all);
    return all.stream().filter(c->c instanceof javax.swing.JLabel).map(c->((javax.swing.JLabel)c).getText()).collect(java.util.stream.Collectors.toList());
  }
}

