      case FIVE: return "~5 minutes";
      case TEN: return "~10 minutes";
      case THIRTY: return "~30 minutes";
      case SIXTY: return "~1 hour";
      case TWO_HOURS: return "~2 hours";
      case FOUR_HOURS: return "~4 hours";
      case EIGHT_HOURS: return "~8 hours";
      case TWELVE_HOURS: return "~12 hours";
      case DAY: return "~24 hours";
      default: return "No preference";
    }
  }

  /** Minutes to send as ?duration=, or 0 for NONE (meaning: leave the query parameter off entirely). */
  int minutes() {
    switch (this) {
      case FIVE: return 5;
      case TEN: return 10;
      case THIRTY: return 30;
      case SIXTY: return 60;
      case TWO_HOURS: return 120;
      case FOUR_HOURS: return 240;
      case EIGHT_HOURS: return 480;
      case TWELVE_HOURS: return 720;
      case DAY: return 1440;
      default: return 0;
    }
  }
}

package com.evi.live;

import java.awt.event.KeyEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.VarClientStr;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;

/**
 * Fills the currently-open GE quantity or price prompt with the cached suggestion, using the same
 * two-line widget/varclient-string write a currently published RuneLite Hub plugin (Flipping
 * Copilot) uses for the same purpose, and the same pattern RuneLite's own built-in GE plugin uses
 * for its 25%/50%/100% quantity-preset buttons. Never touches the Confirm button, never sends a
 * menu action, never selects an item, never types anything outside the single field already open.
 *
 * Resolves which suggestion to fill via GEOffer.resolveOpenSuggestion(suggestionCache,
 * openItemPriceCache) -- see SuggestionHintWidget's own class doc for why: this makes the hotkey
 * work for any item currently open, not only EVI's own top-ranked pick, using exactly the same
 * eligibility gate the hint widget uses so the hotkey never fills a value the player wasn't also
 * shown first.
 */
@Singleton
class SuggestionKeybindHandler {
  private final KeyManager keyManager;
  private final ClientThread clientThread;
  private final Client client;
  private final GEOffer geOffer;
  private final SuggestionCache suggestionCache;
  private final OpenItemPriceCache openItemPriceCache;
  private final EviLiveConfig config;

  private final KeyListener listener = new KeyListener() {
    @Override public void keyTyped(KeyEvent e) { }
    @Override public void keyReleased(KeyEvent e) { }
    @Override public void keyPressed(KeyEvent e) {
      if (e.getKeyCode() == KeyEvent.VK_ENTER) return; // Enter already submits the field; never intercept it.
      if (!config.suggestionKeybind().matches(e)) return;
      clientThread.invokeLater(SuggestionKeybindHandler.this::fill);
    }
  };

  @Inject
  SuggestionKeybindHandler(KeyManager keyManager, ClientThread clientThread, Client client, GEOffer geOffer, SuggestionCache suggestionCache, OpenItemPriceCache openItemPriceCache, EviLiveConfig config) {
    this.keyManager = keyManager;
    this.clientThread = clientThread;
    this.client = client;
    this.geOffer = geOffer;
    this.suggestionCache = suggestionCache;
    this.openItemPriceCache = openItemPriceCache;
    this.config = config;
  }

  void register() { keyManager.registerKeyListener(listener); }
  void unregister() { keyManager.unregisterKeyListener(listener); }

  private void fill() {
    // Same eligibility gate the on-screen hint widget uses to decide what to show, so the hotkey
    // never fills a value the player wasn't also shown first.
    Suggestion s = geOffer.resolveOpenSuggestion(suggestionCache.get(), openItemPriceCache.get());
    switch (geOffer.openFieldFor(s)) {
      case QUANTITY: fillValue(s.quantity); break;
      case BUY_PRICE: fillValue(s.buyPrice); break;
      case SELL_PRICE: fillValue(s.sellPrice); break;
      default: break;
    }
  }

  private void fillValue(long value) {
    Widget input = client.getWidget(ComponentID.CHATBOX_FULL_INPUT);
    if (input == null) return;
    input.setText(value + "*");
    client.setVarcStrValue(VarClientStr.INPUT_TEXT, String.valueOf(value));
  }
}

package com.evi.live;

/**
 * What the bridge should do when EviLiveConfig.forecastHorizon() is enabled and the resulting
 * forecast for a "buy" suggestion is meaningfully unfavorable. Sent to the bridge as
 * ?onForecast=warn|skip on GET /api/suggestion, only when forecastHorizon() isn't OFF (there's
 * nothing to have a policy about otherwise). WARN is the default: the suggestion stays, with the
 * forecast folded into its reasoning text so you can weigh it yourself, same spirit as every other
 * EVI hint -- informational, never a decision made for you. SKIP instead drops that candidate and
 * asks the bridge to rank the next-best one, retrying a bounded number of times (see
 * MAX_FORECAST_ATTEMPTS in bridge/server.mjs) before falling back exactly as if forecasting were off.
 */
public enum ForecastPolicy {
  WARN, SKIP;

  /** RuneLite's config UI renders enum dropdowns using toString(), so this is the visible label. */
  @Override public String toString() {
    return this == SKIP ? "Skip it, rank the next-best instead" : "Warn me, keep the suggestion";
  }

  /** The exact ?onForecast= value the bridge expects. */
  String param() { return name().toLowerCase(); }
}

package com.evi.live;

import java.util.Locale;

/** Validates only local bridge tokens, never Jagex credentials. */
final class PairingKey {
  private PairingKey() {}

  static String normalize(String value) {
    String key = value == null ? "" : value.replace("﻿", "").trim().toLowerCase(Locale.ROOT);
    if (!key.matches("[a-f0-9]{64}")) {
      throw new IllegalArgumentException("Paste only the 64-character RuneLite plugin key from EVI's bridge window.");
    }
    return key;
  }
}

package com.evi.live;

/**
 * How long the player is willing to wait for one trade, in the scanner's own words.
 *
 * Replaces {@link TradeDuration}, whose nine options were labelled in minutes and promised
 * something the market does not deliver. Measured over 60 days of archived prices with
 * tools/hold-length.mjs, replaying the real ranking and holding each pick for exactly as long as
 * the setting claimed: at ~5 minutes, ~30 minutes and ~1 hour, **not one round trip completed
 * inside its own window** at any cash stack tested (50k, 10m and 380m), leaving 100% of the
 * capital still tied up when the window ended. Those settings were not describing fast trades;
 * they were describing trades that had not finished yet.
 *
 * So the options are now the four the scanner already uses, each set to a length that was measured
 * to actually complete:
 *
 * <pre>
 *   at a 10m cash stack        sales completed   realised per sale   capital left stuck
 *   ~1 hour (dropped)                        0                   -                 100%
 *   Fast, 2 hours                           13              70,298                  83%
 *   Medium, 6 hours                         38             177,287                  61%
 *   Overnight, 12 hours                     39             285,156                  55%
 *   Slow, 48 hours                          74             369,945                  27%
 * </pre>
 *
 * Longer genuinely is better here, which is the only reason Slow exists: the standard set for it
 * was that a longer hold has to be verified to help, or it is only added risk. Beyond two days the
 * gain flattens -- 72 hours earned slightly less per sale and only tied up less capital -- so two
 * days is where the improvement stops being unambiguous and the list stops.
 *
 * A new keyName is used deliberately rather than reusing "tradeDuration": RuneLite stores config by
 * keyName, and a stored value naming an option that no longer exists is not something to gamble on.
 * The old setting is kept and hidden, so nothing stored is lost, and every player picks once.
 */
public enum TradePace {
  NONE, FAST, MEDIUM, OVERNIGHT, SLOW;

  /** RuneLite's config UI renders enum dropdowns using toString(), so this is the visible label. */
  @Override public String toString() {
    switch (this) {
      case FAST: return "Fast (~2 hours)";
      case MEDIUM: return "Medium (~6 hours)";
      case OVERNIGHT: return "Overnight (~12 hours)";
      case SLOW: return "Slow (~2 days)";
      default: return "No preference";
    }
  }

  /** Minutes to send as ?duration=, or 0 for NONE (meaning: leave the query parameter off entirely). */
  int minutes() {
    switch (this) {
      case FAST: return 120;
      case MEDIUM: return 360;
      case OVERNIGHT: return 720;
      case SLOW: return 2880;
      default: return 0;
    }
  }
}

package com.evi.live;

/**
 * Mirrors the JSON shape of both the "suggestion" and "openItemPrice" fields returned by GET
 * /api/suggestion (see SuggestionCache and OpenItemPriceCache respectively). Gson-populated; field
 * names must match exactly. buyPrice and sellPrice are always both present together (the bridge's
 * estimate of the current low/high for this item) so the plugin can show/fill whichever one
 * matches the GE prompt actually open, regardless of what action names. For an openItemPrice
 * instance specifically: name/action/source/reasoning are not populated by the bridge (left at
 * their Gson defaults, null) and quantity is always 0 -- see OpenItemPriceCache's own class doc
 * for why, and GEOffer.openFieldFor for how a 0 quantity is used to never offer/fill a fabricated
 * suggested quantity for an item with no track record. persisted is true only when this
 * suggestion came from the bridge's own on-disk reconstruction of open positions (see
 * pickPersistentOpenPosition in suggestions.mjs), used as a restart-safe fallback when the
 * plugin's own live holdItemId/holdQty signal is empty -- never set for a suggestion the bridge
 * built from something observed live this session. That reconstruction can go stale (a position
 * that, in reality, was fully resold through some combination of separate sale offers the
 * automatic matcher didn't perfectly reconcile), so EviLivePlugin.verifyPersistedHolding() checks
 * a persisted suggestion against the player's actual current inventory before trusting it, rather
 * than assuming the journal is always right.
 *
 * buyId identifies the specific GE buy offer behind a "sell" (holding) suggestion, when the bridge
 * can trace one -- both the live path (EviLivePlugin.heldForResale) and the persisted-fallback
 * path carry one when available. Null for a "buy" suggestion (nothing bought yet to identify), and
 * for a holding signal with no single identifiable buy behind it. Sent back unchanged via POST
 * /api/suggestion/personal-use if the player flags this specific holding as personal use --
 * bought for their own use via the GE, not to flip -- so the bridge can exclude that exact buy
 * from ever being surfaced again or counted toward profit, without silently suppressing a real,
 * separate flip of the same item bought some other time. See EviLivePlugin.flagPersonalUse.
 */
class Suggestion {
  int itemId;
  String name;
  String action;
  int quantity;
  long buyPrice;
  long sellPrice;
  String source;
  String reasoning;
  boolean persisted;
  String buyId;
  /** The bridge's handle for this exact shown suggestion, sent back by the "I took this one" button
   * (POST /api/suggestion/accept). It is what lets EVI say what following it is actually worth:
   * without it, the track record is assembled by guessing that an offer placed soon after a
   * suggestion means the suggestion was followed, which cannot tell a followed pick from a trade
   * the player meant to make anyway. Null from an older bridge, in which case the button is hidden
   * rather than shown doing nothing. `accepted` is what the bridge has already recorded for this
   * id, so the button reads as pressed after a reconnect instead of inviting a second press. */
  String id;
  boolean accepted;
  // "Sell" (holding) suggestions only, and only when the real price paid is known -- otherwise
  // null, never estimated. breakEvenPrice: the lowest sell price per unit that doesn't lose GP
  // after GE tax. lossIfSoldNow: set only when selling at sellPrice right now would lose GP, the
  // total GP lost. Shown as a warning; a losing sell is never hidden or blocked.
  Long breakEvenPrice;
  Long lossIfSoldNow;
  /** What the whole trade is worth after tax, computed by the bridge so the panel does not have to
   *  know the Grand Exchange's tax rules to print the headline figure. Null from an older bridge. */
  Long expectedProfit;
  /** What EVI makes of its own pick, as something the sidebar can draw rather than prose to read
   *  (bridge/verdict.mjs). Null when nothing was measured, or when the bridge predates it -- either
   *  way the panel falls back to the reasoning paragraph, so old and new versions still agree. */
  Verdict verdict;

  /** Deliberately a summary of checks that already ran, never a new judgement: every line restates a
   *  figure the bridge had already computed. */
  static class Verdict {
    /** "clear", "caution" or "warn". Anything else is treated as caution rather than trusted. */
    String level;
    String label;
    java.util.List<Check> checks;
  }

  static class Check {
    /** TRUE passed, FALSE failed, null neither -- a stated figure like a break-even price. */
    Boolean ok;
    String text;
  }

  boolean sellsAtLoss() {
    return "sell".equals(action) && lossIfSoldNow != null && lossIfSoldNow > 0;
  }
}

package com.evi.live;

/**
 * How much of your cash stack a single market-wide suggestion may commit, as a plugin config
 * dropdown. Sent to the bridge as ?stackShare=&lt;percent&gt; on GET /api/suggestion; OFF is left off the
 * query string entirely, so choosing it restores exactly the behaviour from before this existed.
 *
 * This is the one setting here chosen from measured evidence rather than judgement. Replaying 90
 * days of archived prices through EVI's own market-wide ranking (tools/backtest.mjs, 352 simulated
 * decisions) found that tier would have lost ~93m gp -- and that the losses were not bad item
 * picks but bad sizing: every large loss was a single expensive item bought with nearly the whole
 * stack and still unsold a day later (Hallowfell x8 for 48.5m, Robin Hood hat x4 for 45.5m). Capping
 * one trade at a quarter of the stack turned that -93m into +67m in the same simulation, while still
 * producing exactly as many suggestions -- it only changes how big they are.
 *
 * It is expressed as a share of YOUR OWN cash rather than a flat gp figure, so it means the same
 * thing to a 5m account as to a 500m one, and it never withholds a suggestion: a capped candidate is
 * still suggested, just smaller, with the reason stated in its reasoning text.
 */
public enum MaxTradeShare {
  OFF, TENTH, QUARTER, THIRD, HALF;

