  }

  /** Percent to send as ?stackShare=, or 0 for OFF (meaning: leave the parameter off entirely). */
  int percent() {
    switch (this) {
      case TENTH: return 10;
      case QUARTER: return 25;
      case THIRD: return 33;
      case HALF: return 50;
      default: return 0;
