package com.evi.live;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/**
 * The five sidebar action icons, drawn rather than shipped as images.
 *
 * <p>Drawing them keeps the plugin jar free of binary assets, which matters for a Plugin Hub
 * submission: there is nothing for a reviewer to have to take on trust, and nothing to go missing
 * when the jar is repacked. Each shape is a few strokes, so the code is shorter than the PNGs would
 * have been anyway.
 *
 * <p>Colour is passed in rather than fixed, because the sidebar has two themes and because a
 * disabled action is drawn in the same shape at a dimmer colour -- Swing only derives a greyed
 * icon automatically for {@code ImageIcon}, so a custom {@code Icon} must supply its own.
 */
final class EviIcons {

  /** Which action a glyph stands for, in the order they appear in the sidebar. */
  enum Glyph { TOOK_IT, PERSONAL_USE, GONE, SKIP, BLOCK }

  private EviIcons() { }

  static Icon of(Glyph glyph, Color colour, int size) {
    return new GlyphIcon(glyph, colour, size);
  }

  private static final class GlyphIcon implements Icon {
    private final Glyph glyph;
    private final Color colour;
    private final int size;

    GlyphIcon(Glyph glyph, Color colour, int size) {
      this.glyph = glyph;
      this.colour = colour;
      this.size = size;
    }

    @Override public int getIconWidth() { return size; }
    @Override public int getIconHeight() { return size; }

    @Override public void paintIcon(Component c, Graphics g, int x, int y) {
      Graphics2D g2 = (Graphics2D) g.create();
      try {
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
        g2.setColor(colour);
        // Everything below is expressed on a 0..1 square and scaled, so one set of coordinates
        // serves whatever icon size the panel asks for.
        final double s = size;
        final double inset = s * 0.06;
        g2.translate(x, y);
        g2.setStroke(new BasicStroke((float) Math.max(1.4, s * 0.115), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        switch (glyph) {
          case TOOK_IT: {
            Path2D.Double p = new Path2D.Double();
            p.moveTo(s * 0.18, s * 0.53);
            p.lineTo(s * 0.41, s * 0.75);
            p.lineTo(s * 0.83, s * 0.25);
            g2.draw(p);
            break;
          }
          case PERSONAL_USE: {
            double head = s * 0.20;
            g2.draw(new Ellipse2D.Double(s * 0.5 - head, s * 0.14, head * 2, head * 2));
            Path2D.Double body = new Path2D.Double();
            body.moveTo(s * 0.17, s * 0.90);
            body.curveTo(s * 0.17, s * 0.60, s * 0.83, s * 0.60, s * 0.83, s * 0.90);
            g2.draw(body);
            break;
          }
          case GONE: {
            // A crate with a line through it: stock that is no longer yours.
            g2.drawRect((int) Math.round(inset), (int) Math.round(s * 0.24),
              (int) Math.round(s - 2 * inset), (int) Math.round(s * 0.58));
            g2.drawLine((int) Math.round(inset), (int) Math.round(s * 0.24),
              (int) Math.round(s - inset), (int) Math.round(s * 0.82));
            break;
          }
          case SKIP: {
            Path2D.Double tri = new Path2D.Double();
            tri.moveTo(s * 0.16, s * 0.15);
            tri.lineTo(s * 0.62, s * 0.5);
            tri.lineTo(s * 0.16, s * 0.85);
            tri.closePath();
            g2.draw(tri);
            g2.drawLine((int) Math.round(s * 0.80), (int) Math.round(s * 0.16),
              (int) Math.round(s * 0.80), (int) Math.round(s * 0.84));
            break;
          }
          case BLOCK: {
            double r = s * 0.37;
            g2.draw(new Ellipse2D.Double(s * 0.5 - r, s * 0.5 - r, r * 2, r * 2));
            double d = r * 0.707;
            g2.drawLine((int) Math.round(s * 0.5 - d), (int) Math.round(s * 0.5 - d),
              (int) Math.round(s * 0.5 + d), (int) Math.round(s * 0.5 + d));
            break;
          }
          default:
            break;
        }
      } finally {
        g2.dispose();
      }
    }
  }
}

package com.evi.live;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.VarClientInt;
import net.runelite.api.VarPlayer;
import net.runelite.api.Varbits;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;

/**
 * Read-only Grand Exchange offer-screen state, mirroring the equivalent accessor in a currently
 * published RuneLite Hub plugin (Flipping Copilot's GrandExchange.java / OfferHandler.java) down
 * to the same widget and varbit IDs. No setters here beyond the fill routine in
 * SuggestionKeybindHandler, and that routine never touches the Confirm button or a menu action.
 */
@Singleton
class GEOffer {
  private static final int CURRENTLY_OPEN_GE_SLOT_VARBIT_ID = 4439;
  private static final int OFFER_TYPE_CHILD_ID = 20;

  /** Which single field, if any, a cached suggestion is currently eligible to be shown/filled for. */
  enum PromptField { NONE, QUANTITY, BUY_PRICE, SELL_PRICE }

  @Inject private Client client;

  boolean isSlotOpen() { return client.getVarbitValue(CURRENTLY_OPEN_GE_SLOT_VARBIT_ID) - 1 != -1; }
  int currentItemId() { return client.getVarpValue(VarPlayer.CURRENT_GE_ITEM); }
  boolean isBuying() { return client.getVarbitValue(Varbits.GE_OFFER_CREATION_TYPE) == 0; }
  boolean isSelling() { return client.getVarbitValue(Varbits.GE_OFFER_CREATION_TYPE) == 1; }

  private Widget chatboxTitle() { return client.getWidget(ComponentID.CHATBOX_TITLE); }
  private Widget offerTypeWidget() {
    Widget container = client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER);
    return container == null ? null : container.getChild(OFFER_TYPE_CHILD_ID);
  }

  /** True only while the "How many do you wish to buy/sell?" quantity prompt is the open chatbox input. */
  boolean isSettingQuantity() {
    Widget title = chatboxTitle();
    if (title == null) return false;
    String text = title.getText();
    return "How many do you wish to buy?".equals(text) || "How many do you wish to sell?".equals(text);
  }

  /** True only while the "Set a price for each item:" prompt is the open chatbox input. */
  boolean isSettingPrice() {
    Widget title = chatboxTitle();
    if (title == null || !"Set a price for each item:".equals(title.getText())) return false;
    Widget offerType = offerTypeWidget();
    if (offerType == null) return false;
    String text = offerType.getText();
    return "Buy offer".equals(text) || "Sell offer".equals(text);
  }

  /**
   * True only while the open chatbox is genuinely the GE quantity/price prompt: the same gate a
   * currently published Hub plugin uses before touching or drawing over anything (VarClientInt.
   * INPUT_TYPE == 7 is the GE quantity/price chatbox, not just any open chatbox), plus a GE slot
   * actually open. Independent of whether any suggestion currently matches.
   */
  boolean isPromptOpen() {
    return chatboxTitle() != null
      && client.getVarcIntValue(VarClientInt.INPUT_TYPE) == 7
      && client.getWidget(ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER) != null
      && isSlotOpen();
  }

  /**
   * Which field (if any) the given suggestion is eligible to be shown/filled for right now: the
   * prompt must actually be open and the suggestion's item must match the item currently selected
   * in the GE offer screen. A price prompt resolves to whichever side the player is actually on
   * (BUY_PRICE while buying, SELL_PRICE while selling) using that side's price from the
   * suggestion, independent of the suggestion's own "action" field -- a suggestion always carries
   * both a buy and a sell price, so the same suggestion can show/fill either side of a flip:
   * the buy price while you're buying the item, and later the sell price while you're selling the
   * same item you already hold. Returns NONE for a null suggestion or a missing/non-positive price
   * on the relevant side. QUANTITY is only offered when s.quantity is actually positive -- always
   * true for a ranked/holding/market suggestion, but deliberately false for a plain
   * OpenItemPriceCache price (see its own class doc): there's no track record to size a quantity by
   * for an item that isn't EVI's own pick, so only its buy/sell price is ever shown/filled, never a
   * fabricated quantity.
   */
  PromptField openFieldFor(Suggestion s) {
    if (s == null || !isPromptOpen() || s.itemId != currentItemId()) return PromptField.NONE;
    if (isSettingQuantity()) return s.quantity > 0 ? PromptField.QUANTITY : PromptField.NONE;
    if (isSettingPrice()) {
      if (isBuying()) return s.buyPrice > 0 ? PromptField.BUY_PRICE : PromptField.NONE;
      if (isSelling()) return s.sellPrice > 0 ? PromptField.SELL_PRICE : PromptField.NONE;
    }
    return PromptField.NONE;
  }

  /**
   * Picks whichever of the two known suggestions actually matches the item currently open in the
   * GE offer screen -- ranked (EVI's own personalized/ranked/holding pick, from SuggestionCache)
   * if it matches, since it carries the richer reasoning and a real suggested quantity; otherwise
   * openItemPrice (a plain live-market price for whatever item IS open, from OpenItemPriceCache,
   * present regardless of flip history or ranking) if that matches instead; otherwise null. This is
   * what makes the hint/hotkey work for any item you're actually trading, not only EVI's current
   * #1 suggestion -- the original limitation the player reported: buying or selling something that
   * either had no reviewed history, or simply wasn't the single top-ranked pick right now, showed
   * no hint and filled nothing at all, even though a live GE price for it was readily available.
   */
  Suggestion resolveOpenSuggestion(Suggestion ranked, Suggestion openItemPrice) {
    int id = currentItemId();
    if (ranked != null && ranked.itemId == id) return ranked;
    if (openItemPrice != null && openItemPrice.itemId == id) return openItemPrice;
    return null;
  }
}

package com.evi.live;

import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.ModifierlessKeybind;

// Every description below is the hover tooltip in RuneLite's settings panel, so each is kept to one
// short plain sentence -- the user reported the old ones, some over 700 characters, as unreadable.
// The reasoning and backtest numbers behind each setting live in README.md (the settings reference
// and the changelog), which is where they can be read properly.
//
// Changing `name` or `description` is safe. NEVER change a `keyName`: RuneLite stores settings by
// keyName, so a renamed key silently resets that setting for every existing user. Moving an item
// into a @ConfigSection or renumbering its position is safe for the same reason -- neither is part
// of the stored key, so every setting below keeps whatever the player already chose.
//
// The four sections were added on 28 Sept 2026 because the panel had grown to seventeen settings in
// one flat list with no grouping at all and -- worse -- with DUPLICATE position numbers: 6 was used
// three times (market-wide, trading profile, suggest from) and 7 three times (max share, trade
// duration, trade pace). RuneLite sorts by position, so those six appeared in an arbitrary order.
// Every position below is unique, numbered in tens by section so a new setting can be slotted
// between two existing ones without renumbering anything.
//
// The ordering principle: the first section holds what a player actually adjusts, the second decides
// where picks come from, and the last two are collapsed because they are either experimental or
// set-once.
@ConfigGroup("evilive")
public interface EviLiveConfig extends Config {

  @ConfigSection(
    name = "What to trade",
    description = "The size, pace and caution of the trades EVI will offer you.",
    position = 10
  )
  String tradeSection = "tradeSection";

  @ConfigSection(
    name = "Where suggestions come from",
    description = "Whether EVI ranks from your own history, the whole market, or both.",
    position = 20
  )
  String sourceSection = "sourceSection";

  @ConfigSection(
    name = "Safety checks",
    description = "Extra warnings. Off by default; each one is opt-in for a measured reason.",
    position = 30,
    closedByDefault = true
  )
  String checksSection = "checksSection";

  @ConfigSection(
    name = "Display and controls",
    description = "The hotkey, the GE overlay and the sidebar colours. Nothing here changes what is suggested.",
    position = 40,
    closedByDefault = true
  )
  String displaySection = "displaySection";

  // ------------------------------------------------------------------ What to trade

  @ConfigItem(
    keyName = "minProfitTier",
    name = "Min predicted profit",
    description = "Skips suggestions predicted to make less than this. Auto scales with your cash stack.",
    section = tradeSection,
    position = 11
  )
  default MinProfitTier minProfitThreshold() {
    return MinProfitTier.AUTO;
  }

  @ConfigItem(
    keyName = "tradePace",
    name = "Trade pace",
    description = "How long you will wait for one trade. Under two hours, round trips rarely finish.",
    section = tradeSection,
    position = 12
  )
  default TradePace tradePace() {
    return TradePace.NONE;
  }

  @ConfigItem(
    keyName = "riskLevel",
    name = "Risk level",
    description = "How much winning history EVI wants before trusting an item. Low is the strictest.",
    section = tradeSection,
    position = 13
  )
  // Low by default: measured over 90 days, the old Medium default did no better than picking an
  // eligible item at random, because one lucky flip could carry an item. See the bridge's own default.
  default RiskLevel riskLevel() {
    return RiskLevel.LOW;
  }

  @ConfigItem(
    keyName = "maxTradeShare",
    name = "Max share of cash per trade",
    description = "The most of your cash a single market-wide suggestion may use.",
    section = tradeSection,
    position = 14
  )
  default MaxTradeShare maxTradeShare() {
    return MaxTradeShare.QUARTER;
  }

  // Default follows the scanner's own Focus switch, so an existing player sees no change.
  @ConfigItem(
    keyName = "suggestionFocus",
    name = "Suggestion focus",
    description = "Which items EVI suggests buying: gear, bulk consumables and ammo, or all. Sales are unaffected.",
    section = tradeSection,
    position = 15
  )
  default SuggestionFocus suggestionFocus() {
    return SuggestionFocus.SAME_AS_SCANNER;
  }

  // New keyName, default ONE, so nothing changes for anyone who does not go looking for it. A large
  // cash stack is the only reason this exists: at 89m the market tier's median suggestion commits
  // about 3.6m and no ranking change moves that, so the rest can only be deployed through further
  // positions. Each one is ranked on the cash left after the ones before it, never on a split stack.
  @ConfigItem(
    keyName = "maxPositions",
    name = "Suggestions at once",
    description = "For a large cash stack. Each extra pick uses only the cash the earlier ones left.",
    section = tradeSection,
    position = 16
  )
  default MaxPositions maxPositions() {
    return MaxPositions.ONE;
  }

  // New keyName, default CAREFUL, so nothing changes for anyone who does not choose it. Measured
  // before it was offered: see PositionSizing and the 28 Sept 2026 README entry.
  @ConfigItem(
    keyName = "positionSizing",
    name = "Position sizing",
    description = "Bigger buys more of thinly traded items. More profit per trade, slightly more risk.",
    section = tradeSection,
    position = 17
  )
  default PositionSizing positionSizing() {
    return PositionSizing.CAREFUL;
  }

  @ConfigItem(
    keyName = "tradeDuration",
    name = "Target trade duration",
    description = "Replaced by Trade pace. Kept so nothing you chose is lost; it no longer has any effect.",
    section = tradeSection,
    position = 19,
    hidden = true
  )
  default TradeDuration tradeDuration() {
    return TradeDuration.NONE;
  }

  // --------------------------------------------------- Where suggestions come from

  @ConfigItem(
    keyName = "suggestionSource",
    name = "Suggest from",
    description = "Your own history first, the best of both, or the whole market ignoring your history.",
    section = sourceSection,
    position = 21
  )
  default SuggestionSource suggestionSource() {
    return SuggestionSource.HISTORY_FIRST;
  }

  @ConfigItem(
    keyName = "includeMarketSuggestions",
    name = "Include market-wide suggestions",
    description = "When your own trade history has nothing, suggest from the whole GE catalogue.",
    section = sourceSection,
    position = 22
  )
  default boolean includeMarketSuggestions() {
    return false;
  }

  @ConfigItem(
    keyName = "tradingProfile",
    name = "Trading profile",
    description = "Starter sticks to cheap, untaxed, fast-selling items. Standard uses the whole catalogue.",
    section = sourceSection,
    position = 23
  )
  default TradingProfile tradingProfile() {
    return TradingProfile.STARTER;
  }

  @ConfigItem(
    keyName = "suggestIdleInventory",
    name = "Suggest selling idle inventory",
    description = "Also suggests selling valuable inventory items EVI never saw you buy.",
    section = sourceSection,
    position = 24
  )
  default boolean suggestIdleInventory() {
    return false;
  }

  @ConfigItem(
    keyName = "itemBlocklist",
    name = "Item blocklist (item IDs)",
    description = "Item IDs never to suggest, e.g. 4151,995. Easier: the sidebar's Block icon.",
    section = sourceSection,
    position = 25
  )
  default String itemBlocklist() {
    return "";
  }

  // ------------------------------------------------------------------ Safety checks

  // Renamed from "Price forecast for suggestions". Calibration over 90 days found the forecast's
  // direction calls wrong more often than chance, so it no longer predicts price at all; what it
  // measurably predicts is whether a trade's sell side fills, and that is all it is now used for
  // (see bridge/fillOutlook.mjs). Same keyName, so existing choices are kept.
  @ConfigItem(
    keyName = "forecastHorizon",
    name = "Exit-risk check",
    description = "Warns when items with a similar recent price pattern often failed to sell in time.",
    section = checksSection,
    position = 31
  )
  default ForecastHorizon forecastHorizon() {
    return ForecastHorizon.OFF;
  }

  // Off by default, under a NEW keyName. It originally shipped on by default under keyName
  // "marginSafetyCushion", and RuneLite writes every default into the stored profile the first time
  // the plugin loads -- so just flipping the default under the old key would have left anyone who'd
  // already run that build stuck with a stored "true". Measured against live Wiki data, that check
  // blocked every candidate (0 of 40 market-wide picks, 0 of 5 personal-history picks passed,
  // including a real, high-volume thin-margin flip) and the bridge then returned no suggestion at
  // all: its volatility estimate counts the ordinary bounce between an item's buy and sell prices
  // (the very margin being flipped) as price movement, and scales it over a fixed 2-hour window.
  // Stays opt-in until that measurement is redesigned -- see the 2026-09-17 README entry.
  @ConfigItem(
    keyName = "requireMarginAboveNoise",
    name = "Require margin above price noise",
    description = "Experimental and far too strict: skips almost every trade. Best left off.",
    section = checksSection,
    position = 32
  )
  default boolean marginSafetyCushion() {
    return false;
  }

  // Hidden, not removed: it currently has no effect. "Skip" used to drop a candidate on an
  // unfavourable forecast, but the forecast was measured to be wrong more often than right, so
  // skipping is switched off in the bridge (FORECAST_MAY_DROP_CANDIDATES in suggestions.mjs). A
  // setting that does nothing is the least clear thing a settings panel can show. Kept under its
  // keyName so a stored choice survives, and so it can be unhidden if a recalibrated forecast earns
  // the right to rule trades out again.
  @ConfigItem(
    keyName = "forecastPolicy",
    name = "On an unfavorable forecast",
    description = "Inactive: the exit-risk check only warns and never skips a trade.",
    section = checksSection,
    position = 33,
    hidden = true
  )
  default ForecastPolicy forecastPolicy() {
    return ForecastPolicy.WARN;
  }

  // ----------------------------------------------------------- Display and controls

  @ConfigItem(
    keyName = "showSuggestionHint",
    name = "Show GE hints",
    description = "Shows EVI's suggestion in the GE offer prompt and highlights the suggested item in search.",
    section = displaySection,
    position = 41
  )
  default boolean showSuggestionHint() {
    return true;
  }

  @ConfigItem(
    keyName = "suggestionKeybind",
    name = "Fill suggestion hotkey",
    description = "Fills in EVI's suggested quantity or price while a GE prompt is open. Never confirms an offer.",
    section = displaySection,
    position = 42
  )
  default Keybind suggestionKeybind() {
    return new ModifierlessKeybind(KeyEvent.VK_F8, 0);
  }

  // Colours only: nothing about what is suggested, warned about or sent depends on this. Default is
  // the look the panel has always had, so an existing player sees no change unless they pick one.
  @ConfigItem(
    keyName = "panelTheme",
    name = "Panel colours",
    description = "Colours for EVI's sidebar: RuneLite's own, or the dashboard's Old School parchment.",
    section = displaySection,
    position = 43
  )
  default PanelTheme panelTheme() {
    return PanelTheme.RUNELITE;
  }
}

package com.evi.live;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.api.Client;

/**
 * Display-only help finding EVI's currently suggested item in the Grand Exchange's item-search
 * results list (the list shown once you've clicked the search icon and started typing): a
 * translucent rectangle over the suggestion's own row, matched by item ID. Same visual technique
 * a currently published RuneLite Hub plugin (Flipping Copilot's
 * WidgetHighlightOverlay/HighlightController.highlightItemInSearch) uses for its own item-search
 * highlight, read directly from its published source.
 *
 * An earlier version of this class also painted an "EVI suggests: <name>" label of its own near
 * the offer-setup panel, through several repositioning attempts (see UPDATE-NOTES.md's dated
 * entries) that never quite landed reliably -- that display-only row was removed entirely.
 * SuggestionItemSelectWidget now covers that same job properly instead: a real, clickable widget
 * placed inside the GE's own item-search results list (matching where Flipping Copilot's own
 * "Copilot item: <icon> <name>" row actually lives and behaves, confirmed against its published
 * source), not a painted guess at pixel coordinates.
 *
 * This overlay itself never adds a click handler or touches the widget tree -- cannot select,
 * confirm, or fill anything by itself; picking the item is up to you, or the click-to-jump row in
 * SuggestionItemSelectWidget. Governed by the same showSuggestionHint config toggle as the chatbox
 * hint line and that widget.
 */
@Singleton
final class SuggestionSearchHighlightOverlay extends Overlay {
  // Shared with the sidebar panel and every other overlay via EviTheme, instead of a locally
  // hand-rolled color -- see EviTheme's own class doc for why.
  private static final Color HIGHLIGHT = EviTheme.brand(90);

  @Inject private Client client;
  @Inject private GEOffer geOffer;
  @Inject private SuggestionCache suggestionCache;
  @Inject private EviLiveConfig config;

  @Inject
  SuggestionSearchHighlightOverlay() {
    setPosition(OverlayPosition.DYNAMIC);
    setLayer(OverlayLayer.ABOVE_WIDGETS);
  }

  @Override
  public Dimension render(Graphics2D graphics) {
    if (!config.showSuggestionHint() || !geOffer.isSlotOpen() || geOffer.isPromptOpen()) return null;
    Suggestion s = suggestionCache.get();
    // Nothing left to point at once the suggested item is actually the one selected -- the
    // quantity/price prompt (and SuggestionHintWidget) takes over from here.
    if (s == null || geOffer.currentItemId() == s.itemId) return null;
    Widget row = findSuggestionRow(s.itemId);
    if (row != null) {
      Rectangle bounds = row.getBounds();
      if (bounds != null && !bounds.isEmpty()) {
        graphics.setColor(HIGHLIGHT);
        graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
      }
    }
    return null;
  }

  // The GE's own item-search results list; a distinct widget group from the quantity/price
  // chatbox prompt SuggestionHintWidget/GEOffer work with, only populated/visible while the
  // search box is actually open and showing matches.
  private Widget findSuggestionRow(int itemId) {
    Widget results = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
    if (results == null || results.isHidden()) return null;
    Widget[] children = results.getDynamicChildren();
    if (children == null) return null;
    for (Widget child : children) {
      if (child != null && !child.isHidden() && child.getItemId() == itemId) return child;
    }
    return null;
  }
}

package com.evi.live;

import javax.inject.Singleton;

/** Holds the most recently fetched suggestion in memory. Written by the poller, read by the hotkey handler. */
@Singleton
class SuggestionCache {
  private volatile Suggestion current;
  Suggestion get() { return current; }
  void set(Suggestion s) { current = s; }
}
